var Q27 = [
{n:1, q:'La Ley de Protección de la Seguridad Ciudadana es la...', o:{a:'Ley 3/2015.',b:'Ley 4/2015.',c:'Ley Orgánica 3/2015.',d:'Ley Orgánica 4/2015.'}, correct:'d', why:{d:'La Ley de Protección de la Seguridad Ciudadana es la Ley Orgánica 4/2015, de 30 de marzo.'}},
{n:2, q:'La Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, contiene:', o:{a:'Un Preámbulo, 6 Capítulos y 54 artículos.',b:'7 disposiciones adicionales, 1 disposición transitoria, 1 disposición derogatoria y 5 disposiciones finales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La LO 4/2015 contiene, además de su articulado, 7 disposiciones adicionales, 1 disposición transitoria, 1 disposición derogatoria y 5 disposiciones finales.'}},
{n:3, q:'El régimen sancionador de la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, está establecido en su ...', o:{a:'Capítulo III.',b:'Capítulo IV.',c:'Capítulo V.',d:'Capítulo VI.'}, correct:'c', why:{c:'El régimen sancionador de la LO 4/2015 está establecido en su Capítulo V.'}},
{n:4, q:'El régimen sancionador de la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, está establecido en los...', o:{a:'Artículos 30 a 54.',b:'Artículos 35 a 54.',c:'Artículos 30 a 55.',d:'Artículos 35 a 55.'}, correct:'a', why:{a:'El régimen sancionador de la LO 4/2015 se establece en los artículos 30 a 54.'}},
{n:5, q:'El Capítulo V de la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, dedicado al Régimen Sancionador está dividido en...', o:{a:'Dos Secciones.',b:'Tres Secciones.',c:'Cuatro Secciones.',d:'Cinco Secciones.'}, correct:'b', why:{b:'El Capítulo V de la LO 4/2015 está dividido en tres Secciones: infracciones y sanciones, órganos competentes, y procedimiento.'}},
{n:6, q:'La Sección 1ª del Capítulo V de la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, dedicado al Régimen Sancionador, se denomina...', o:{a:'Procedimiento Sancionador.',b:'Prescripción y caducidad.',c:'Infracciones y Sanciones.',d:'Sujetos responsables, órganos competentes y reglas generales sobre las infracciones y la aplicación de las sanciones.'}, correct:'d', why:{d:'La Sección 1ª del Capítulo V de la LO 4/2015 se denomina "Sujetos responsables, órganos competentes y reglas generales sobre las infracciones y la aplicación de las sanciones".'}},
{n:7, q:'La Sección 2ª del Capítulo V de la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, dedicado al Régimen Sancionador, se denomina...', o:{a:'Procedimiento Sancionador.',b:'Prescripción y caducidad.',c:'Infracciones y Sanciones.',d:'Sujetos responsables, órganos competentes y reglas generales sobre las infracciones y la aplicación de las sanciones.'}, correct:'c', why:{c:'La Sección 2ª del Capítulo V de la LO 4/2015 se denomina "Infracciones y Sanciones".'}},
{n:8, q:'La Sección 3ª del Capítulo V de la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, dedicado al Régimen Sancionador, se denomina...', o:{a:'Procedimiento Sancionador.',b:'Prescripción y caducidad.',c:'Infracciones y Sanciones.',d:'Sujetos responsables, órganos competentes y reglas generales sobre las infracciones y la aplicación de las sanciones.'}, correct:'a', why:{a:'La Sección 3ª del Capítulo V de la LO 4/2015 se denomina "Procedimiento Sancionador".'}},
{n:9, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la perturbación de la seguridad ciudadana en actos públicos, que no sea constitutiva de infracción penal, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que la perturbación de la seguridad ciudadana en actos públicos es una infracción grave.'}},
{n:10, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, cuando no constituya infracción penal, la perturbación grave de la seguridad ciudadana que se produzca de reuniones o manifestaciones frente a las sedes del Congreso de los Diputados, el Senado y las asambleas legislativas de las comunidades autónomas, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36.2 LO 4/2015 establece que la perturbación grave frente a sedes del Congreso, Senado y asambleas legislativas autonómicas es infracción grave.'}},
{n:11, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la proyección de haces de luz sobre pilotos o conductores de medios de transporte, que puedan deslumbrarles o distraer su atención, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'a', why:{a:'El art. 35 LO 4/2015 establece que la proyección de haces de luz sobre pilotos o conductores que pueda deslumbrarlos es una infracción muy grave.'}},
{n:12, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, obstaculizar la vía con mobiliario urbano, ocasionando una alteración grave de la seguridad ciudadana, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que obstaculizar la vía con mobiliario urbano ocasionando alteración grave de la seguridad ciudadana es infracción grave.'}},
{n:13, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la celebración de reuniones en lugares de tránsito público incumpliendo lo preceptuado en el artículo 4.2 de la Ley Orgánica 9/1983, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que la celebración de reuniones en lugares de tránsito incumpliendo el art. 4.2 LO 9/1983 es infracción leve.'}},
{n:14, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el uso no autorizado de imágenes de miembros de las Fuerzas y Cuerpos de Seguridad que pueda poner en peligro la seguridad personal o familiar de los agentes, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36.23 LO 4/2015 establece que el uso no autorizado de imágenes de miembros de las FCS que ponga en peligro su seguridad personal o familiar es infracción grave.'}},
{n:15, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la ocupación de cualquier inmueble, vivienda o edificio ajenos, siempre que no sea constitutivo de infracción penal, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37.7 LO 4/2015 establece que la ocupación de inmueble, vivienda o edificio ajenos sin constituir infracción penal es infracción leve.'}},
{n:16, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la celebración de reuniones en lugares de tránsito público incumpliendo lo preceptuado en el artículo 11 de la Ley Orgánica 9/1983, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que la celebración de reuniones incumpliendo el art. 11 LO 9/1983 es infracción leve.'}},
{n:17, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, cuando no constituya infracción penal, la perturbación del desarrollo de una reunión o manifestación lícita, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que la perturbación del desarrollo de una reunión o manifestación lícita es infracción grave cuando no constituye infracción penal.'}},
{n:18, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la negativa de acceso en fábricas, locales, establecimientos, embarcaciones y aeronaves, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que la negativa al acceso a fábricas, locales y establecimientos cuando sea exigible es infracción grave.'}},
{n:19, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la celebración de manifestaciones incumpliendo lo preceptuado en el artículo 8 de la Ley Orgánica 9/1983, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que la celebración de manifestaciones incumpliendo el art. 8 LO 9/1983 es infracción leve.'}},
{n:20, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, cuando no constituya delito, y siempre que con ello se causen perjuicios muy graves, el comercio de explosivos catalogados careciendo de la autorización o documentación requeridas, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'a', why:{a:'El art. 35 LO 4/2015 establece que el comercio de explosivos catalogados sin autorización, causando perjuicios muy graves, es infracción muy grave.'}},
{n:21, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la perturbación de la seguridad ciudadana en espectáculos deportivos es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que la perturbación de la seguridad ciudadana en espectáculos deportivos es infracción grave.'}},
{n:22, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana el consumo de drogas tóxicas en lugares públicos es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36.16 LO 4/2015 establece que el consumo o tenencia de drogas tóxicas en lugares públicos es infracción grave.'}},
{n:23, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, cuando no constituya delito, el traslado de personas con cualquier tipo de vehículo, con el objeto de facilitar a éstas el acceso a estupefacientes o sustancias psicotrópicas, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que el traslado de personas para facilitar acceso a estupefacientes, sin constituir delito, es infracción grave.'}},
{n:24, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el incumplimiento de las restricciones de circulación peatonal o itinerario con ocasión de un acto público, que provoque alteraciones menores en el mismo, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que el incumplimiento de restricciones de circulación peatonal provocando alteraciones menores es infracción leve.'}},
{n:25, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, cuando no constituya delito, el hecho de portar un arma prohibida es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que portar un arma prohibida sin constituir delito es infracción grave.'}},
{n:26, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, causar desórdenes en establecimientos públicos que produzcan una alteración grave de la seguridad ciudadana, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que causar desórdenes en establecimientos públicos con alteración grave de la seguridad ciudadana es infracción grave.'}},
{n:27, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la intrusión en instalaciones en las que se presten servicios básicos para la comunidad, cuando se haya producido una interferencia grave en su funcionamiento, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que la intrusión en instalaciones de servicios básicos causando interferencia grave es infracción grave.'}},
{n:28, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, cuando no constituya delito, y siempre que con ello se causen perjuicios muy graves, el transporte de armas reglamentarias careciendo de la autorización o documentación requeridas, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'a', why:{a:'El art. 35 LO 4/2015 establece que el transporte de armas reglamentarias sin autorización, causando perjuicios muy graves, es infracción muy grave.'}},
{n:29, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, cuando no sea constitutivo de infracción penal, la perturbación de la seguridad ciudadana en solemnidades y oficios religiosos, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que la perturbación de la seguridad ciudadana en solemnidades y oficios religiosos es infracción grave.'}},
{n:30, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, obstaculizar la vía pública con neumáticos u otros objetos, ocasionando una alteración grave de la seguridad ciudadana, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que obstaculizar la vía pública con neumáticos u otros objetos causando alteración grave es infracción grave.'}},
{n:31, q:'Según la Ley Orgánica 4/2015, de la Seguridad Ciudadana, la proyección de haces de luz sobre miembros de las Fuerzas y Cuerpos de Seguridad para impedir o dificultar el ejercicio de sus funciones es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'c', why:{c:'El art. 36 LO 4/2015 establece que la proyección de haces de luz sobre miembros de las FCS para dificultar sus funciones es infracción grave; según el solucionario la respuesta es c) (Menos Grave).'}},
{n:32, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, cuando no constituya infracción penal, la falta de respeto y consideración a un miembro de las Fuerzas y Cuerpos de Seguridad, en el ejercicio de sus funciones de protección de la seguridad, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37.4 LO 4/2015 establece que la falta de respeto y consideración a miembros de las FCS en el ejercicio de sus funciones es infracción leve.'}},
{n:33, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, si no constituye delito, los actos de obstrucción que pretendan impedir a cualquier autoridad el ejercicio legítimo de sus funciones, cuando se produzcan al margen de los procedimientos legalmente establecidos, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que los actos de obstrucción al ejercicio legítimo de funciones de autoridad son infracción grave.'}},
{n:34, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la negativa a la disolución de reuniones y manifestaciones en lugares de tránsito público ordenadas por la autoridad competente, cuando concurran los supuestos del artículo 5 de la Ley Orgánica 9/1983, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que la negativa a la disolución de reuniones/manifestaciones ordenada por la autoridad concurriendo los supuestos del art. 5 LO 9/1983 es infracción grave.'}},
{n:35, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, cuando no constituya delito, y siempre que con ello se causen perjuicios muy graves, la fabricación de artículos pirotécnicos careciendo de la autorización o documentación requeridas, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'a', why:{a:'El art. 35 LO 4/2015 establece que la fabricación de artículos pirotécnicos sin autorización causando perjuicios muy graves es infracción muy grave.'}},
{n:36, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, cuando no constituya delito, y siempre que con ello se causen perjuicios muy graves, la reparación de armas reglamentarias incumpliendo la normativa de aplicación es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'a', why:{a:'El art. 35 LO 4/2015 establece que la reparación de armas reglamentarias incumpliendo la normativa causando perjuicios muy graves es infracción muy grave.'}},
{n:37, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la perturbación de la seguridad ciudadana en reuniones a las que asistan numerosas personas, cuando no constituya infracción penal, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que la perturbación de la seguridad ciudadana en reuniones numerosas es infracción grave.'}},
{n:38, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, las acciones u omisiones que impidan u obstaculicen el funcionamiento de los servicios de emergencia, provocando o incrementando un riesgo para la vida o integridad de las personas, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que obstaculizar los servicios de emergencia incrementando riesgo para la vida es infracción grave.'}},
{n:39, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el uso no autorizado de datos profesionales de miembros de las Fuerzas y Cuerpos de Seguridad que pueda poner en riesgo el éxito de una operación, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que el uso no autorizado de datos profesionales de miembros de las FCS que ponga en riesgo el éxito de una operación es infracción grave.'}},
{n:40, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, cuando no constituya infracción penal, la incitación a la realización de actos que atenten contra la libertad sexual, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que la incitación a actos contra la libertad sexual sin constituir infracción penal es infracción leve.'}},
{n:41, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, cuando no constituya infracción penal, la permanencia en cualquier vivienda en contra de la voluntad de su propietario o arrendatario, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37.7 LO 4/2015 establece que la permanencia en vivienda ajena contra la voluntad del propietario o arrendatario es infracción leve.'}},
{n:42, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el sobrevuelo en las inmediaciones de infraestructuras en las que se prestan servicios básicos para la comunidad, cuando se haya generado un riesgo para la vida o la integridad física de las personas, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'a', why:{a:'El art. 35 LO 4/2015 establece que el sobrevuelo sobre infraestructuras de servicios básicos generando riesgo para personas es infracción muy grave.'}},
{n:43, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la celebración de espectáculos públicos quebrantando la suspensión ordenada por la autoridad por motivos de seguridad pública, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'a', why:{a:'El art. 35 LO 4/2015 establece que la celebración de espectáculos quebrantando la suspensión por motivos de seguridad pública es infracción muy grave.'}},
{n:44, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, cuando no constituya delito y siempre que con ello se causen perjuicios muy graves, el almacenamiento de artículos pirotécnicos excediendo de los límites autorizados, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'a', why:{a:'El art. 35 LO 4/2015 establece que el almacenamiento de artículos pirotécnicos excediendo límites, causando perjuicios muy graves, es infracción muy grave.'}},
{n:45, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, cuando no constituya delito, los actos de obstrucción que pretendan impedir a cualquier autoridad la ejecución de acuerdos o resoluciones judiciales o administrativas, suponen una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que los actos de obstrucción para impedir la ejecución de resoluciones judiciales o administrativas son infracción grave.'}},
{n:46, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, las acciones u omisiones que impidan u obstaculicen el funcionamiento de los servicios de emergencia, agravando las consecuencias del suceso que motive su actuación, constituyen una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que obstaculizar los servicios de emergencia agravando las consecuencias es infracción grave.'}},
{n:47, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el sobrevuelo de infraestructuras e instalaciones en las que se prestan servicios básicos para la comunidad, que haya producido una interferencia grave en su funcionamiento, constituye infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que el sobrevuelo sobre instalaciones de servicios básicos produciendo interferencia grave en su funcionamiento es infracción grave.'}},
{n:48, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, cuando no constituya delito o infracción grave la exhibición de objetos peligrosos para la vida e integridad física de las personas con ánimo intimidatorio, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que la exhibición de objetos peligrosos con ánimo intimidatorio sin constituir delito o infracción grave es infracción leve.'}},
{n:49, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el uso no autorizado de datos personales o profesionales de autoridades, que pueda poner en riesgo la seguridad de las instalaciones protegidas, constituye infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que el uso no autorizado de datos de autoridades que ponga en riesgo la seguridad de instalaciones protegidas es infracción grave.'}},
{n:50, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la omisión o insuficiencia de medidas para garantizar la conservación de la documentación de armas y explosivos, constituye infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que la omisión o insuficiencia de medidas de conservación de documentación de armas y explosivos es infracción leve.'}},
{n:51, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la tolerancia del consumo ilegal de drogas tóxicas, estupefacientes o sustancias psicotrópicas en locales o establecimientos públicos, constituye infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36.18 LO 4/2015 establece que la tolerancia del consumo ilegal de drogas en locales o establecimientos públicos es infracción grave.'}},
{n:52, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la falta de denuncia de pérdida o sustracción de la documentación de armas o explosivos, constituye infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que la falta de denuncia de pérdida o sustracción de documentación de armas o explosivos es infracción leve.'}},
{n:53, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, cuando no constituya infracción penal, la alegación de datos falsos para la obtención del documento nacional de identidad, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que la alegación de datos falsos para obtener el DNI es infracción grave.'}},
{n:54, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, ejecutar actos de exhibición obscena que no sean constitutivos de infracción penal, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37.5 LO 4/2015 establece que ejecutar actos de exhibición obscena sin constituir infracción penal es infracción leve.'}},
{n:55, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el abandono de instrumentos u otros efectos empleados en el consumo ilícito de drogas tóxicas en lugares, vías, establecimientos públicos o transportes colectivos, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36.17 LO 4/2015 establece que el abandono de instrumentos de consumo de drogas en lugares o transportes públicos es infracción grave.'}},
{n:56, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el incumplimiento de las restricciones a la navegación reglamentariamente impuestas a las embarcaciones de alta velocidad y aeronaves ligeras, constituye infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que el incumplimiento de restricciones de navegación para embarcaciones de alta velocidad y aeronaves ligeras es infracción grave.'}},
{n:57, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la ocupación de la vía pública con infracción de lo dispuesto en la ley o contra la decisión adoptada por la autoridad competente, constituye infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que la ocupación de la vía pública en infracción de la ley o contra decisión de la autoridad es infracción leve.'}},
{n:58, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la intrusión en el recinto de una instalación donde se prestan servicios básicos para la comunidad, generando un riesgo para la vida o la integridad física de las personas, constituye infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'a', why:{a:'El art. 35 LO 4/2015 establece que la intrusión en instalaciones de servicios básicos generando riesgo para la vida es infracción muy grave.'}},
{n:59, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la negativa a identificarse a requerimiento de la autoridad o sus agentes, cuando no sea constitutiva de delito, constituye infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36.6 LO 4/2015 establece que la negativa a identificarse a requerimiento de la autoridad sin constituir delito es infracción grave.'}},
{n:60, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la reparación de armas reglamentarias careciendo de la documentación o autorización requeridas, cuando no sea constitutiva de delito, constituye infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que la reparación de armas reglamentarias sin documentación es infracción grave cuando no constituye delito.'}},
{n:61, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la falta de colaboración con las Fuerzas y Cuerpos de Seguridad en la averiguación de delitos, que pueda poner en riesgo la seguridad ciudadana en los supuestos previstos en el artículo 7 de esta ley, constituye infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36.7 LO 4/2015 establece que la falta de colaboración con las FCS en la averiguación de delitos, poniendo en riesgo la seguridad ciudadana, es infracción grave.'}},
{n:62, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el consumo de bebidas alcohólicas en lugares públicos, cuando perturbe gravemente la seguridad ciudadana, constituye infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37.17 LO 4/2015 establece que el consumo de bebidas alcohólicas en lugares públicos perturbando gravemente la seguridad ciudadana es infracción leve.'}},
{n:63, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la alegación de datos falsos o inexactos en los procesos de identificación a requerimiento de la autoridad o sus agentes, cuando no sea constitutiva de delito, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36.6 LO 4/2015 establece que la alegación de datos falsos en procesos de identificación es infracción grave.'}},
{n:64, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, exhibir o usar armas prohibidas, cuando no sea constitutiva de infracción penal, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que exhibir o usar armas prohibidas sin constituir infracción penal es infracción grave.'}},
{n:65, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la exhibición de armas de modo intimidatorio, cuando no sea constitutiva de infracción penal, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que la exhibición de armas de modo intimidatorio sin constituir infracción penal es infracción grave.'}},
{n:66, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el consumo de bebidas alcohólicas en los transportes públicos que perturbe gravemente la tranquilidad ciudadana, constituye infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que el consumo de bebidas alcohólicas en transportes públicos perturbando la tranquilidad ciudadana es infracción leve.'}},
{n:67, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el uso de armas de modo negligente, cuando no sea constitutivo de delito, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que el uso negligente de armas sin constituir delito es infracción grave.'}},
{n:68, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el uso de armas con licencia, fuera de los lugares habilitados para su uso, cuando no sea constitutivo de infracción penal, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que el uso de armas con licencia fuera de los lugares habilitados, sin constituir infracción penal, es infracción grave.'}},
{n:69, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la solicitud de servicios sexuales retribuidos en zonas de tránsito público que puedan generar un riesgo para la seguridad vial, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36.11 LO 4/2015 establece que la solicitud de servicios sexuales retribuidos en zonas de tránsito que genere riesgo para la seguridad vial es infracción grave.'}},
{n:70, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el escalamiento de edificios sin autorización cuando exista un riesgo cierto de que se ocasionen daños a las persona o a los bienes, constituye infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que el escalamiento de edificios sin autorización con riesgo de daños es infracción leve.'}},
{n:71, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el comercio de cartuchería careciendo de la documentación o autorización requeridas, cuando no sea constitutivo de delito, constituye infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que el comercio de cartuchería sin documentación o autorización es infracción grave cuando no constituye delito.'}},
{n:72, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, dejar sueltos animales feroces o dañinos, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37.16 LO 4/2015 establece que dejar sueltos animales feroces o dañinos es infracción leve.'}},
{n:73, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el transporte de artículos pirotécnicos incumpliendo la normativa de aplicación, cuando no sea constitutivo de delito, es infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que el transporte de artículos pirotécnicos incumpliendo la normativa es infracción grave cuando no constituye delito.'}},
{n:74, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la omisión negligente de la denuncia de sustracción o extravío de la documentación personal legalmente exigida, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que la omisión negligente de denuncia de sustracción o extravío de documentación personal es infracción leve.'}},
{n:75, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la aceptación de servicios sexuales retribuidos en las proximidades de un centro educativo, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36.11 LO 4/2015 establece que la aceptación de servicios sexuales retribuidos en las proximidades de un centro educativo es infracción grave.'}},
{n:76, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el almacenamiento de explosivos catalogados excediendo de los límites autorizados, cuando no sea constitutivo de delito, es una infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que el almacenamiento de explosivos catalogados superando los límites sin constituir delito es infracción grave.'}},
{n:77, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, abandonar animales domésticos en condiciones en que pueda peligrar su vida constituye infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que abandonar animales domésticos en condiciones que pongan en peligro su vida es infracción leve.'}},
{n:78, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la remoción de vallas colocadas por las Fuerzas y Cuerpos de Seguridad para delimitar perímetros de seguridad, constituye infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que la remoción de vallas de perímetros de seguridad de las FCS es infracción leve.'}},
{n:79, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el uso de armas de modo temerario, que no constituya infracción penal, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que el uso temerario de armas sin constituir infracción penal es infracción grave.'}},
{n:80, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la solicitud o aceptación por el demandante de servicios sexuales retribuidos en las proximidades de parques infantiles o espacios de ocio accesibles a menores de edad, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36.11 LO 4/2015 establece que la solicitud o aceptación de servicios sexuales retribuidos cerca de parques infantiles o espacios de ocio para menores es infracción grave.'}},
{n:81, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la remoción de encintados u otros elementos fijos o móviles colocados por las Fuerzas y Cuerpos de Seguridad para delimitar perímetros de seguridad que no constituya infracción grave, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que la remoción de encintados de perímetros de seguridad sin constituir infracción grave es infracción leve.'}},
{n:82, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el escalamiento de monumentos sin autorización cuando exista un riesgo cierto de que se ocasionen daños a las personas o a los bienes, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que el escalamiento de monumentos sin autorización con riesgo de daños es infracción leve.'}},
{n:83, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, las irregularidades en la cumplimentación de los registros previstos en esta ley, o la omisión de las comunicaciones obligatorias en los plazos establecidos, siempre que no constituya infracción penal, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que las irregularidades en los registros o la omisión de comunicaciones obligatorias es infracción leve.'}},
{n:84, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el uso público e indebido de uniformes, insignias o condecoraciones oficiales, que pueda generar engaño acerca de la condición de quien los use, siempre que no constituya infracción penal, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que el uso indebido de uniformes o insignias oficiales generando engaño es infracción grave.'}},
{n:85, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el incumplimiento de la obligación de obtener la documentación personal legalmente exigida, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que el incumplimiento de la obligación de obtener la documentación personal legalmente exigida es infracción leve.'}},
{n:86, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el deslucimiento de bienes muebles o inmuebles de uso o servicio público, cuando no constituya infracción penal, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que el deslucimiento de bienes de uso público sin constituir infracción penal es infracción leve.'}},
{n:87, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la insuficiencia de las medidas de seguridad obligatorias en la fabricación, reparación, almacenamiento, circulación y comercio de armas reglamentarias, que no constituya infracción penal, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que la insuficiencia de medidas de seguridad en la fabricación y comercio de armas reglamentarias es infracción grave.'}},
{n:88, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el uso público e indebido de réplicas de insignias o condecoraciones oficiales, que pueda generar engaño acerca de la condición de quien los use, siempre que no constituya infracción penal, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que el uso público de réplicas de insignias generando engaño es infracción grave.'}},
{n:89, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la tercera y posteriores pérdidas o extravíos de la documentación personal legalmente exigida en el plazo de un año, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que la tercera y posteriores pérdidas de documentación en el plazo de un año es infracción leve.'}},
{n:90, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el hecho de causar daños en bienes muebles o inmuebles privados en la vía pública, que no constituya infracción penal, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que causar daños en bienes privados en la vía pública sin constituir infracción penal es infracción leve.'}},
{n:91, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, el uso público e indebido de uniformes de los servicios de emergencia, que pueda generar engaño acerca de la condición de quien los use, siempre que no constituya infracción penal, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'b', why:{b:'El art. 36 LO 4/2015 establece que el uso indebido de uniformes de servicios de emergencia generando engaño es infracción grave.'}},
{n:92, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, la negativa a entregar la documentación personal legalmente exigida, cuando se hubiese acordado su retirada o retención, se considera infracción de carácter:', o:{a:'Muy grave.',b:'Grave.',c:'Menos Grave.',d:'Leve.'}, correct:'d', why:{d:'El art. 37 LO 4/2015 establece que la negativa a entregar la documentación personal cuando se haya acordado su retención es infracción leve.'}},
{n:93, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, y con relación a su régimen sancionador, indique la respuesta que no es correcta.', o:{a:'Estarán exentos de responsabilidad por las infracciones cometidas los menores de catorce años.',b:'En caso de que la infracción sea cometida por un menor de catorce años, la autoridad competente lo pondrá en conocimiento del Ministerio Fiscal.',c:'La responsabilidad por las infracciones cometidas recaerá directamente en el autor del hecho en que consista la infracción.',d:'En el caso de que un solo hecho constituya dos o más infracciones, o cuando una de ellas sea medio necesario para cometer la otra, la conducta será sancionada por aquella infracción que aplique una menor sanción.'}, correct:'d', why:{d:'La opción d) es incorrecta: en concurso de infracciones se aplica el principio de que se sanciona por la infracción más grave, no por la de menor sanción.'}},
{n:94, q:'Indique la respuesta que no es correcta. Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, los hechos susceptibles de ser calificados con arreglo a dos o más preceptos de esta u otra Ley se sancionarán observando que...', o:{a:'El precepto más amplio o complejo absorberá el que sancione las infracciones consumidas en aquel.',b:'El precepto general se aplicará con preferencia al especial.',c:'El precepto más grave excluirá los que sancionen el hecho con una sanción menor.',d:'Cuando una acción u omisión sea tomada en consideración como criterio de graduación de la sanción o como circunstancia que determine la calificación de la infracción no podrá ser sancionada como infracción independiente.'}, correct:'b', why:{b:'La opción b) es incorrecta: en materia sancionadora se aplica el precepto especial con preferencia al general, no al contrario.'}},
{n:95, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, y en lo que respecta a los órganos competentes para sancionar, indique la respuesta que no es correcta.', o:{a:'Los Delegados del Gobierno en las comunidades autónomas y en las ciudades de Ceuta y Melilla, son competentes para la sanción de las infracciones graves y leves.',b:'El Ministro del Interior es competente para la sanción de las infracciones graves y muy graves en grado máximo.',c:'El Secretario de Estado de Seguridad es competente para la sanción de infracciones muy graves en grado medio y en grado mínimo.',d:'Serán competentes para imponer las sanciones tipificadas en esta Ley las autoridades correspondientes de la Comunidad Autónoma en el ámbito de sus competencias en materia de seguridad ciudadana.'}, correct:'b', why:{b:'La opción b) es incorrecta: el Ministro del Interior es competente para la sanción de las infracciones muy graves, no las graves y muy graves en grado máximo como se describe.'}},
{n:96, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, y en lo que respecta a la competencia de los alcaldes para imponer sanciones en esta materia, indique la respuesta correcta.', o:{a:'Los alcaldes son competentes, en todo caso, para sancionar las infracciones leves que se cometan en espacios públicos municipales.',b:'Los alcaldes son competentes para sancionar las infracciones leves que afecten a bienes de titularidad local, siempre que no sean consecuencia de actuaciones que la entidad local tenga el deber jurídico de soportar.',c:'Los alcaldes son competentes para sancionar las infracciones que se cometan en espacios públicos municipales o afecten a bienes de titularidad local, siempre que ostenten competencia sobre la materia de acuerdo con la legislación específica.',d:'Los alcaldes son competentes para sancionar las infracciones se cometan en espacios públicos municipales, siempre y cuando la competencia no se halle atribuida a otra autoridad, en su legislación específica.'}, correct:'c', why:{c:'El art. 42.3 LO 4/2015 establece que los alcaldes son competentes para sancionar las infracciones cometidas en espacios públicos municipales o que afecten a bienes de titularidad local, siempre que ostenten competencia sobre la materia.'}},
{n:97, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, y en lo que respecta a la prescripción de las infracciones, indique la respuesta correcta.', o:{a:'Las infracciones administrativas graves tipificadas en esta Ley prescriben al año de haberse cometido.',b:'Las infracciones administrativas muy graves tipificadas en esta Ley prescriben a los dos años de haberse cometido.',c:'Las infracciones administrativas leves tipificadas en esta Ley prescriben a los seis meses de haberse cometido.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 44 LO 4/2015 establece que las infracciones muy graves prescriben a los 3 años, las graves al año y las leves a los 6 meses; según el solucionario la respuesta es d).'}},
{n:98, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, y en lo que respecta a la prescripción de las infracciones, indique la respuesta incorrecta.', o:{a:'La prescripción se interrumpirá por cualquier actuación administrativa de la que tenga conocimiento formal el interesado dirigida a la sanción de la infracción, reanudándose el cómputo del plazo de prescripción si el procedimiento estuviera paralizado más de tres meses por causa no imputable al presunto responsable.',b:'Los plazos señalados en esta Ley se computarán desde el día en que se haya cometido la infracción.',c:'Se interrumpirá la prescripción como consecuencia de la apertura de un procedimiento judicial penal, hasta que la autoridad judicial comunique al órgano administrativo su finalización.',d:'En los casos de infracciones continuadas y de infracciones de efectos permanentes, los plazos se computarán, respectivamente, desde el día en que se realizó la última infracción y desde que se eliminó la situación ilícita.'}, correct:'a', why:{a:'La opción a) es incorrecta: la prescripción se reanuda si el procedimiento está paralizado más de un mes (no tres meses) por causa no imputable al presunto responsable conforme al art. 44 LO 4/2015.'}},
{n:99, q:'Indique la respuesta que no es correcta. Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana...', o:{a:'Las infracciones muy graves se sancionan con multa de 30.001 a 500.000 euros.',b:'Las infracciones graves se sancionan con multa de 601 a 30.000 euros.',c:'Las infracciones leves se sancionan con multa de 100 a 600 euros.',d:'La responsabilidad civil derivada de una infracción será siempre solidaria entre todos los causantes del daño.'}, correct:'a', why:{a:'La opción a) es incorrecta: las infracciones muy graves se sancionan con multa de 30.001 a 600.000 euros (no 500.000) conforme al art. 39 LO 4/2015.'}},
{n:100, q:'Indique la respuesta que no es correcta. Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, además de la multa que corresponda, se puede imponer como sanción accesoria...', o:{a:'La clausura de las fábricas, locales o establecimientos, desde seis meses y un día a dos años, por infracciones muy graves.',b:'La clausura de las fábricas, locales o establecimientos hasta seis meses, por infracciones graves.',c:'La suspensión definitiva de las licencias, autorizaciones o permisos.',d:'La retirada de las armas y de las licencias o permisos correspondientes a las mismas.'}, correct:'c', why:{c:'La opción c) es incorrecta: la LO 4/2015 prevé la suspensión temporal de licencias como sanción accesoria, pero no la suspensión definitiva.'}},
{n:101, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, y con respecto a la prescripción de las sanciones administrativas, indique la respuesta que no es correcta...', o:{a:'Las sanciones impuestas por infracciones muy graves prescribirán a los tres años.',b:'Las sanciones impuestas por infracciones graves prescribirán a los dos años.',c:'Las sanciones impuestas por infracciones leves prescribirán al año.',d:'Los plazos de prescripción de las sanciones administrativas se computan desde el día en que adquiera firmeza en vía administrativa la resolución por la que se impone la sanción.'}, correct:'d', why:{d:'La opción d) es incorrecta: los plazos de prescripción de las sanciones se computan desde el día siguiente a aquel en que adquiera firmeza la resolución sancionadora, no desde que adquiera firmeza en vía administrativa.'}},
{n:102, q:'Según la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, y en lo que respecta a las medidas provisionales que pueden adoptar los agentes de la autoridad, antes del inicio del procedimiento sancionador, indique la respuesta correcta...', o:{a:'Instrumentos utilizados para la comisión de la infracción.',b:'Dinero directamente obtenido con la infracción.',c:'Frutos o productos directamente obtenidos con la infracción.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 47 LO 4/2015 establece que los agentes pueden adoptar como medidas provisionales la incautación de instrumentos, dinero y frutos obtenidos con la infracción.'}},
{n:103, q:'En lo que respecta al procedimiento sancionador establecido en la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, indique la respuesta que no es correcta.', o:{a:'El procedimiento caducará transcurrido un año desde su incoación sin que se haya notificado la resolución.',b:'Una vez notificado el acuerdo de incoación del procedimiento para la sanción de infracciones graves o leves, el interesado dispondrá de un plazo de 20 días para realizar el pago voluntario con reducción de la sanción de multa, o para formular las alegaciones y proponer o aportar las pruebas que estime oportunas.',c:'Las medidas provisionales acordadas podrán ser modificadas o levantadas cuando varíen las circunstancias que motivaron su adopción y, en todo caso, se extinguirán con la resolución que ponga fin al procedimiento.',d:'El procedimiento sancionador abreviado no será de aplicación a las infracciones muy graves.'}, correct:'b', why:{b:'La opción b) es incorrecta: el plazo para el pago voluntario o formulación de alegaciones no es de 20 días sino de 15 días hábiles conforme al procedimiento de la LO 4/2015.'}},
{n:104, q:'En lo que respecta al valor probatorio de las declaraciones de los agentes de la autoridad, en el procedimiento sancionador establecido en la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana, indique la respuesta que no es correcta...', o:{a:'Solo es de aplicación este principio a las infracciones leves o graves, cometidas en vías o lugares públicos.',b:'Las denuncias, atestados o actas formulados por los agentes de la autoridad en ejercicio de sus funciones constituirán base suficiente para adoptar la resolución que proceda.',c:'Para que tengan valor probatorio estas declaraciones es necesario que los agentes de la autoridad hayan presenciado los hechos, y los ratifiquen en el caso de que hayan sido negados por los denunciados.',d:'El valor probatorio de estas declaraciones se presume, salvo prueba en contrario, y sin perjuicio de que aquéllos deban aportar el expediente todos los elementos probatorios disponibles.'}, correct:'a', why:{a:'La opción a) es incorrecta: el valor probatorio de las declaraciones de los agentes no se limita solo a infracciones leves o graves en vías públicas; se aplica con carácter general.'}},
{n:105, q:'En la Constitución Española de 1978, el derecho a la protección de datos de carácter personal se entiende incluido en el...', o:{a:'Artículo 18.3.',b:'Artículo 18.4.',c:'Artículo 20.1 a).',d:'Artículo 20.1 d).'}, correct:'b', why:{b:'El derecho a la protección de datos de carácter personal ha sido reconocido por el TC como derivado del art. 18.4 CE, que habilita al legislador para limitar el uso de la informática.'}},
{n:106, q:'En el ámbito de la Unión Europea, la norma básica sobre protección de datos es...', o:{a:'La Directiva UE 679/2016 del Parlamento Europeo y del Consejo.',b:'El Reglamento UE 769/2016 del Parlamento Europeo y del Consejo.',c:'El Reglamento UE 679/2016 del Parlamento Europeo y del Consejo.',d:'La Directiva UE 769/2016 del Parlamento Europeo y del Consejo.'}, correct:'c', why:{c:'El Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo (RGPD) es la norma básica sobre protección de datos en el ámbito de la Unión Europea.'}},
{n:107, q:'En España, la protección de datos personales y garantía de los derechos digitales se contiene en...', o:{a:'La Ley 3/2018.',b:'La Ley Orgánica 3/2018.',c:'La Ley 7/2021.',d:'La Ley Orgánica 7/2021.'}, correct:'b', why:{b:'La protección de datos personales y garantía de los derechos digitales se regula en la Ley Orgánica 3/2018, de 5 de diciembre (LOPDGDD).'}},
{n:108, q:'La Ley Orgánica de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales es la ...', o:{a:'Ley Orgánica 8/2021.',b:'Ley Orgánica 7/2021.',c:'Ley Orgánica 6/2020.',d:'Ley Orgánica 7/2020.'}, correct:'b', why:{b:'La Ley Orgánica 7/2021, de 26 de mayo, regula la protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales.'}},
{n:109, q:'El Reglamento UE 679/2016, relativo a la protección de personas físicas en lo que respecta al tratamiento de datos personales y a la libre circulación de estos datos, no es aplicable al tratamiento de datos personales...', o:{a:'Efectuado por una persona física en el ejercicio de actividades exclusivamente personales o domésticas.',b:'Por parte de las autoridades competentes con fines de prevención, investigación, detección o enjuiciamiento de infracciones penales, o de ejecución de sanciones penales.',c:'En el ejercicio de una actividad no comprendida en el ámbito de aplicación del Derecho de la Unión.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El RGPD no es aplicable en los tres supuestos citados: actividades personales o domésticas, fines penales por autoridades competentes y actividades fuera del Derecho de la UE.'}},
{n:110, q:'Según el Reglamento UE 679/2016, relativo a la protección de personas físicas en lo que respecta al tratamiento de datos personales y a la libre circulación de estos datos, se entenderá por "datos personales"...', o:{a:'Toda información sobre una persona física identificada o identificable.',b:'Los datos pertenecientes a las personas jurídicas que sirvan para identificarlas en el tráfico jurídico y distinguirlas de otras personas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 4.1 RGPD define datos personales como toda información sobre una persona física identificada o identificable.'}},
{n:111, q:'Según el Reglamento UE 679/2016, relativo a la protección de personas físicas en lo que respecta al tratamiento de datos personales y a la libre circulación de estos datos, se considera "persona física identificable"...', o:{a:'A toda persona cuya identidad pueda determinarse, directa o indirectamente, en particular mediante un identificador.',b:'Al marcado de los datos de carácter personal conservados con el fin de limitar su tratamiento en el futuro.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 4.1 RGPD define persona física identificable como aquella cuya identidad pueda determinarse directa o indirectamente, en particular mediante un identificador.'}},
{n:112, q:'Según el Reglamento UE 679/2016, relativo a la protección de personas físicas en lo que respecta al tratamiento de datos personales y a la libre circulación de estos datos, se considera "tratamiento"...', o:{a:'Al marcado de los datos de carácter personal conservados con el fin de limitar su tratamiento en el futuro.',b:'A cualquier operación o conjunto de operaciones realizadas sobre datos personales, ya sea por procedimientos automatizados o no, como la recogida, registro, organización, estructuración, conservación, adaptación o modificación, extracción, consulta, utilización, comunicación por transmisión, difusión o cualquier otra forma de habilitación de acceso, cotejo o interconexión, limitación, supresión o destrucción.',c:'A todo conjunto estructurado de datos personales, accesibles con arreglo a criterios determinados, ya sea centralizado, descentralizado o repartido de forma funcional o geográfica.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 4.2 RGPD define tratamiento como cualquier operación o conjunto de operaciones realizadas sobre datos personales por procedimientos automatizados o no.'}},
{n:113, q:'Según el Reglamento UE 679/2016, la persona física o jurídica, autoridad pública, servicio u otro organismo que trate datos personales por cuenta del responsable de tratamiento, se denomina...', o:{a:'Destinatario.',b:'Encargado de tratamiento.',c:'Tercero.',d:'Representante.'}, correct:'b', why:{b:'El art. 4.8 RGPD define encargado del tratamiento como la persona física o jurídica que trate datos personales por cuenta del responsable del tratamiento.'}},
{n:114, q:'Según el Reglamento UE 679/2016, relativo a la protección de personas físicas en lo que respecta al tratamiento de datos personales y a la libre circulación de estos datos, se considera "responsable de tratamiento"...', o:{a:'A la persona física o jurídica establecida en la Unión que, habiendo sido designada por escrito por el encargado del tratamiento, represente al encargado en lo que respecta a sus respectivas obligaciones en virtud de este Reglamento.',b:'A la persona física o jurídica, autoridad pública, servicio u otro organismo que, solo o junto con otros, determine los fines y medios del tratamiento.',c:'A la persona física o jurídica, autoridad pública, servicio u otro organismo al que se comuniquen datos personales, se trate o no de un tercero.',d:'A la autoridad pública independiente establecida por un Estado miembro con arreglo a lo dispuesto en el artículo 51 de este Reglamento.'}, correct:'b', why:{b:'El art. 4.7 RGPD define responsable del tratamiento como la persona física o jurídica que, solo o junto con otros, determine los fines y medios del tratamiento.'}},
{n:115, q:'Según el Reglamento UE 679/2016, relativo a la protección de personas físicas en lo que respecta al tratamiento de datos personales y a la libre circulación de estos datos, se considera "consentimiento del interesado"...', o:{a:'A toda manifestación de voluntad libre, específica, informada e inequívoca por la que el interesado acepta, ya sea mediante una declaración o una clara acción afirmativa, el tratamiento de datos personales que le conciernen.',b:'A las políticas de protección de datos asumidas por un responsable o encargado del tratamiento establecido en el territorio de un Estado miembro para transferencias o un conjunto de transferencias de datos personales a un responsable o encargado en uno o más países terceros, dentro de un grupo empresarial o una unión de empresas dedicadas a una actividad económica conjunta.',c:'A la objeción a una propuesta de decisión sobre la existencia o no de infracción del presente Reglamento, o sobre la conformidad con el presente Reglamento de acciones previstas en relación con el responsable o el encargado del tratamiento.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 4.11 RGPD define consentimiento como toda manifestación de voluntad libre, específica, informada e inequívoca por la que el interesado acepta el tratamiento de sus datos personales.'}},
{n:116, q:'Según el Reglamento UE 679/2016, y en lo que respecta a los principios relativos al tratamiento de datos, indique la respuesta que no es correcta...', o:{a:'Los datos personales serán adecuados, pertinentes y limitados a lo necesario en relación con los fines para los que son tratados.',b:'Los datos personales serán tratados de manera segura, limitando el acceso de aquellas autoridades o funcionarios que no tengan la formación suficiente y acreditada en esta materia.',c:'Los datos personales serán recogidos con fines determinados, explícitos y legítimos.',d:'Los datos personales serán exactos y, si fuera necesario, actualizados.'}, correct:'b', why:{b:'La opción b) es incorrecta: el RGPD no establece restricciones de acceso basadas en la formación de los funcionarios; el principio de integridad y confidencialidad se refiere a la seguridad técnica y organizativa, no a criterios formativos.'}},
{n:117, q:'Según el Reglamento UE 679/2016, y en lo que respecta a los principios relativos al tratamiento de datos, indique la respuesta correcta...', o:{a:'Los datos personales serán tratados de manera lícita, leal y transparente en relación con el interesado.',b:'Los datos personales serán mantenidos de forma que se permita la identificación de los interesados durante no más tiempo del necesario para los fines del tratamiento.',c:'Los datos personales serán tratados de tal manera que se garantice una seguridad adecuada de los datos personales, incluida la protección contra el tratamiento no autorizado o ilícito y contra su pérdida, destrucción o daño accidental.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 5 RGPD establece todos los principios relativos al tratamiento de datos personales, incluyendo los de licitud/lealtad/transparencia, limitación del plazo de conservación y seguridad.'}},
{n:118, q:'Según el Reglamento UE 679/2016, y en lo que respecta a la licitud en el tratamiento de los datos personales, indique la respuesta que no es correcta.', o:{a:'El tratamiento solo será lícito si es necesario para la ejecución de un contrato aunque el interesado no sea su parte, o para la aplicación a petición de éste de medidas precontractuales.',b:'El tratamiento solo será lícito si el interesado dio su consentimiento para el tratamiento de sus datos personales para uno o varios fines específicos.',c:'El tratamiento solo será lícito si es necesario para proteger intereses vitales del interesado o de otra persona física.',d:'El tratamiento solo será lícito si es necesario para el cumplimiento de una obligación legal aplicable al responsable del tratamiento.'}, correct:'a', why:{a:'La opción a) es incorrecta: el tratamiento es lícito cuando es necesario para la ejecución de un contrato en el que el interesado SEA parte, no cuando no lo sea.'}},
{n:119, q:'Según el Reglamento UE 679/2016, y en lo que respecta a la licitud en el tratamiento de los datos personales:', o:{a:'El tratamiento solo será lícito si es necesario para el cumplimiento de una misión realizada en interés público o en el ejercicio de poderes públicos conferidos al responsable del tratamiento.',b:'El tratamiento solo será lícito si es necesario para la satisfacción de intereses legítimos perseguidos por el responsable del tratamiento o por un tercero, siempre que sobre dichos intereses no prevalezcan los intereses o los derechos y libertades fundamentales del interesado que requieran la protección de datos personales, en particular cuando el interesado sea un niño.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 6 RGPD establece que el tratamiento es lícito cuando es necesario para misiones de interés público o cuando prevalecen los intereses legítimos del responsable sobre los del interesado.'}},
{n:120, q:'Según el Reglamento UE 679/2016, y en lo que respecta a las condiciones para el consentimiento en el tratamiento de los datos personales, indique la respuesta que no es correcta...', o:{a:'Cuando el tratamiento se base en el consentimiento del interesado, el responsable deberá ser capaz de demostrar que aquel consintió el tratamiento de sus datos personales.',b:'Si el consentimiento del interesado se da en el contexto de una declaración escrita que también se refiera a otros asuntos, la solicitud de consentimiento se presentará de tal forma que se distinga claramente de los demás asuntos.',c:'Para revocar su consentimiento, el interesado tendrá que esperar a que se produzca la caducidad del mismo, comunicándolo al responsable del tratamiento y a la administración interesada.',d:'Al evaluar si el consentimiento se ha dado libremente, se tendrá en cuenta en la mayor medida posible el hecho de si, entre otras cosas, la ejecución de un contrato, incluida la prestación de un servicio, se supedita al consentimiento al tratamiento de datos personales que no son necesarios para la ejecución de dicho contrato.'}, correct:'c', why:{c:'La opción c) es incorrecta: el interesado puede retirar su consentimiento en cualquier momento, sin necesidad de esperar a su caducidad, conforme al art. 7 RGPD.'}},
{n:121, q:'Según el Reglamento UE 679/2016, y en relación con la oferta directa a niños de servicios de la sociedad de la información, el tratamiento de los datos personales de un niño se considerará lícito cuando tenga como mínimo...', o:{a:'13 años.',b:'14 años.',c:'16 años.',d:'18 años.'}, correct:'c', why:{c:'El art. 8 RGPD establece que el tratamiento de datos de menores para servicios de la sociedad de la información se considerará lícito a partir de los 16 años (aunque los Estados miembros pueden reducir este límite a no menos de 13 años).'}},
{n:122, q:'Según el Reglamento UE 679/2016, queda prohibido el tratamiento de datos personales que revelen...', o:{a:'Datos biométricos dirigidos a identificar de manera unívoca a una persona física.',b:'Datos relativos a la vida sexual o la orientación sexual de una persona física.',c:'Datos personales que revelen el origen étnico o racial.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 9 RGPD prohíbe el tratamiento de categorías especiales de datos, incluyendo datos biométricos, relativos a la vida sexual/orientación sexual y de origen étnico o racial.'}},
{n:123, q:'Según el Reglamento UE 679/2016, como regla general, queda prohibido el tratamiento de datos personales que revelen el origen étnico o racial, las opiniones políticas, las convicciones religiosas o filosóficas, o la afiliación sindical, y el tratamiento de datos genéticos, datos biométricos dirigidos a identificar de manera unívoca a una persona física, datos relativos a la salud o datos relativos a la vida sexual o la orientación sexual de una persona física. Sin embargo está prohibición no es aplicable cuando...', o:{a:'El tratamiento es necesario por razones de un interés público esencial, sobre la base del Derecho de la Unión o de los Estados miembros, que debe ser proporcionado al objetivo perseguido, respetar en lo esencial el derecho a la protección de datos y establecer medidas adecuadas y específicas para proteger los intereses y derechos fundamentales del interesado.',b:'El tratamiento es necesario para proteger intereses vitales del interesado o de otra persona física, en el supuesto de que el interesado no esté capacitado, física o jurídicamente, para dar su consentimiento.',c:'El tratamiento se refiere a datos personales que el interesado ha hecho manifiestamente públicos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 9.2 RGPD establece varias excepciones a la prohibición general del tratamiento de categorías especiales, incluyendo los tres supuestos citados.'}},
{n:124, q:'Según el Reglamento UE 679/2016, cuando los datos personales se obtengan del interesado, no es información que deberá facilitarse:', o:{a:'Los datos biométricos dirigidos a identificar de manera unívoca a la persona física.',b:'La identidad y los datos de contacto del responsable y, en su caso, de su representante.',c:'Los datos de contacto del delegado de protección de datos, en su caso.',d:'Los fines del tratamiento a que se destinan los datos personales y la base jurídica del tratamiento.'}, correct:'a', why:{a:'Los datos biométricos no son información que deba facilitarse al interesado conforme al art. 13 RGPD; lo que debe facilitarse es información sobre el propio tratamiento.'}},
{n:125, q:'Según el Reglamento UE 679/2016, cuando los datos personales se obtengan del interesado, es información que deberá facilitarse:', o:{a:'Los destinatarios o las categorías de destinatarios de los datos personales, en su caso.',b:'En su caso, la intención del responsable de transferir datos personales a un tercer país u organización internacional.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 13 RGPD establece que cuando se obtienen datos del interesado debe informársele de los destinatarios y de las posibles transferencias a terceros países.'}},
{n:126, q:'En relación con la información que el responsable del tratamiento facilitará al interesado en el momento en que se obtengan sus datos personales por consentimiento, según el Reglamento UE 679/2016, no se encuentra:', o:{a:'El derecho del interesado a presentar una reclamación ante el Juez de lo Contencioso que resulte competente según las reglas de cada estado miembro.',b:'El plazo durante el cual se conservarán los datos personales o, cuando no sea posible, los criterios utilizados para determinar este plazo.',c:'La existencia del derecho a solicitar al responsable del tratamiento el acceso a los datos personales relativos al interesado, y su rectificación o supresión, o la limitación de su tratamiento, o a oponerse al tratamiento.',d:'La existencia de decisiones automatizadas, incluida la elaboración de perfiles.'}, correct:'a', why:{a:'El art. 13 RGPD no incluye el derecho a reclamación ante el Juez de lo Contencioso entre la información que debe facilitarse; sí incluye el derecho a reclamar ante la autoridad de control.'}},
{n:127, q:'En relación con la información que deberá facilitarse al interesado cuando los datos personales no se hayan obtenido de éste, según el Reglamento UE 679/2016, no se encuentra/n:', o:{a:'La identidad y los datos de contacto del responsable y, en su caso, de su representante.',b:'La intención del responsable de transferir datos personales a un destinatario dentro de su propia organización.',c:'Las categorías de datos personales de que se trate.',d:'Los destinatarios o las categorías de destinatarios de los datos personales, en su caso.'}, correct:'b', why:{b:'El art. 14 RGPD no incluye entre la información obligatoria la intención de transferir datos a un destinatario dentro de la propia organización del responsable.'}},
{n:128, q:'En relación con la información que deberá facilitarse al interesado cuando los datos personales no se hayan obtenido de éste, según el Reglamento UE 679/2016, se encuentra/n:', o:{a:'Los datos de contacto del delegado de protección de datos, en su caso.',b:'Los fines del tratamiento a que se destinan los datos personales, así como la base jurídica del tratamiento.',c:'La intención del responsable de transferir datos personales a un destinatario en un tercer país u organización internacional.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 14 RGPD establece que cuando los datos no se obtienen del interesado, debe informársele de los datos de contacto del DPD, los fines del tratamiento y las posibles transferencias internacionales.'}},
{n:129, q:'Según el Reglamento UE 679/2016, y en relación con el registro de las actividades de tratamiento, indique la respuesta correcta.', o:{a:'Cada responsable y, en su caso, su representante llevarán un registro de las actividades de tratamiento efectuadas bajo su responsabilidad.',b:'Cada encargado y, en su caso, el representante del encargado, llevará un registro de todas las categorías de actividades de tratamiento efectuadas por cuenta de un responsable.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 30 RGPD establece que tanto los responsables como los encargados del tratamiento deben llevar su respectivo registro de actividades de tratamiento.'}},
{n:130, q:'Según el Reglamento UE 679/2016, y en lo que se refiere al Delegado de Protección de Datos, indique la respuesta que no es correcta.', o:{a:'Debe ser designado por el responsable o encargado de tratamiento.',b:'Es obligatoria su designación cuando el tratamiento lo lleve a cabo una autoridad u organismo público, excepto los tribunales que actúen en ejercicio de su función judicial y las notarías.',c:'Es obligatoria su designación en las actividades principales del responsable o del encargado que consistan en operaciones de tratamiento que, en razón de su naturaleza, alcance y/o fines, requieran una observación habitual y sistemática de interesados a gran escala.',d:'Es obligatoria su designación cuando las actividades principales del responsable o del encargado consistan en el tratamiento a gran escala de categorías especiales de datos con arreglo al artículo 9 de este Reglamento, o de datos personales relativos a condenas e infracciones penales a que se refiere su artículo 10.'}, correct:'b', why:{b:'La opción b) es incorrecta: la excepción a la obligación de designar DPD no incluye las notarías; solo los tribunales que actúen en ejercicio de su función judicial están exceptuados.'}},
{n:131, q:'Según el Reglamento UE 679/2016, y en lo que se refiere al Delegado de Protección de Datos, no es correcto que:', o:{a:'Un grupo empresarial podrá nombrar un único delegado de protección de datos siempre que sea fácilmente accesible desde cada establecimiento.',b:'Cuando el responsable o el encargado del tratamiento sea una autoridad u organismo público, se podrá designar un único delegado de protección de datos para varias de estas autoridades u organismos.',c:'El delegado de protección de datos será designado atendiendo a sus cualidades profesionales y, en particular, a sus conocimientos especializados del Derecho y la práctica en materia de protección de datos y a su capacidad para desempeñar las funciones indicadas.',d:'El delegado de protección de datos no podrá formar parte de la plantilla del responsable o del encargado del tratamiento, debiendo desempeñar sus funciones en el marco de un contrato de servicios.'}, correct:'d', why:{d:'La opción d) es incorrecta: el DPD puede ser miembro de la plantilla del responsable o encargado del tratamiento, o desempeñar sus funciones en virtud de un contrato de servicios.'}},
{n:132, q:'Según el Reglamento UE 679/2016, y en lo que se refiere a las funciones del Delegado de Protección de Datos, no es una de ellas:', o:{a:'Actuar como punto de contacto de la autoridad de control para cuestiones relativas al tratamiento, salvo en lo que se refiere a la consulta previa.',b:'Informar y asesorar al responsable o al encargado del tratamiento y a los empleados que se ocupen del tratamiento de las obligaciones que les corresponden en materia de protección de datos.',c:'Cooperar con la autoridad de control.',d:'Ofrecer el asesoramiento que se le solicite acerca de la evaluación de impacto relativa a la protección de datos y supervisar su aplicación.'}, correct:'a', why:{a:'La opción a) es incorrecta: el DPD actúa como punto de contacto de la autoridad de control para todas las cuestiones relativas al tratamiento, incluidas las consultas previas.'}},
{n:133, q:'La Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, no es de aplicación....', o:{a:'A los tratamientos excluidos del ámbito de aplicación del Reglamento UE 679/2016.',b:'A los tratamientos de datos de personas fallecidas, sin perjuicio de lo establecido en el artículo 3 de esta Ley orgánica.',c:'A los tratamientos sometidos a la normativa sobre protección de materias clasificadas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La LO 3/2018 no es de aplicación a los tratamientos excluidos del RGPD, a los datos de fallecidos (art. 3) y a los sometidos a la normativa de materias clasificadas.'}},
{n:134, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, y en lo que respecta a los datos personales de las personas fallecidas, indique la respuesta que no es correcta....', o:{a:'En caso de fallecimiento de personas con discapacidad, las facultades de acceso a los datos del fallecido, así como su rectificación o supresión solo podrán ejercerse por quienes realicen las funciones de apoyo.',b:'Las personas vinculadas al fallecido por razones familiares o de hecho así como sus herederos podrán dirigirse a los responsable o encargado del tratamiento al objeto de solicitar el acceso a los datos personales de aquella y, en su caso, su rectificación o supresión.',c:'Las personas vinculadas al fallecido por razones familiares o de hecho así como sus herederos no podrán acceder a los datos del causante, ni solicitar su rectificación o supresión, cuando la persona fallecida lo hubiese prohibido expresamente o así lo establezca una ley.',d:'Las personas o instituciones a las que el fallecido hubiese designado expresamente para ello podrán solicitar, con arreglo a las instrucciones recibidas, el acceso a los datos personales de este y, en su caso su rectificación o supresión.'}, correct:'b', why:{b:'La opción b) es incorrecta: las personas vinculadas al fallecido por razones familiares pueden solicitar el acceso a los datos solo dentro de los límites legales y no de forma irrestricta como sugiere la opción.'}},
{n:135, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, y en lo que respecta al tratamiento de los datos de los menores de edad:', o:{a:'El tratamiento de los datos personales de un menor de edad únicamente podrá fundarse en su consentimiento cuando sea mayor de catorce años.',b:'Es indiferente la edad del menor en los supuestos en que la ley exija la asistencia de los titulares de la patria potestad o tutela para la celebración del acto o negocio jurídico en cuyo contexto se recaba el consentimiento para el tratamiento.',c:'El tratamiento de los datos de los menores de catorce años, fundado en el consentimiento, solo será lícito si consta el del titular de la patria potestad o tutela, y con el alcance que determinen éstos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La LO 3/2018 establece que el consentimiento de menores mayores de 14 años es válido para el tratamiento, que en menores de 14 años se requiere consentimiento parental, y que la edad es relevante en actos jurídicos.'}},
{n:136, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, y en lo que respecta al derecho de acceso, indique la respuesta que no es correcta.', o:{a:'El derecho de acceso se entenderá otorgado si el responsable del tratamiento facilitara al afectado un sistema de acceso remoto, directo y seguro a los datos personales que garantice, de modo permanente, el acceso a su totalidad.',b:'Se podrá considerar repetitivo el ejercicio del derecho de acceso en más de una ocasión durante el plazo de un año, a menos que exista causa legítima para ello.',c:'El derecho de acceso del afectado se ejercitará de acuerdo con lo establecido en el artículo 15 del Reglamento (UE) 2016/679.',d:'Cuando el afectado elija un medio distinto al que se le ofrece que suponga un coste desproporcionado, la solicitud de acceso será considerada excesiva, por lo que dicho afectado asumirá el exceso de costes que su elección comporte.'}, correct:'b', why:{b:'La opción b) es incorrecta: el art. 13 LO 3/2018 establece que puede considerarse repetitivo el acceso ejercido en más de dos ocasiones (no una) en el plazo de doce meses.'}},
{n:137, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, indique la respuesta que no es correcta.', o:{a:'El derecho de oposición, así como los derechos relacionados con las decisiones individuales automatizadas, incluida la realización de perfiles, se ejercerán de acuerdo con lo establecido, respectivamente, en los artículos 21 y 22 del Reglamento (UE) 2016/679.',b:'El derecho de supresión se ejercerá de acuerdo con lo establecido en el artículo 16 del Reglamento (UE) 2016/679.',c:'El derecho a la limitación del tratamiento se ejercerá de acuerdo con lo establecido en el artículo 18 del Reglamento (UE) 2016/679.',d:'El derecho a la portabilidad se ejercerá de acuerdo con lo establecido en el artículo 20 del Reglamento (UE) 2016/679.'}, correct:'b', why:{b:'La opción b) es incorrecta: el derecho de supresión ("derecho al olvido") se regula en el art. 17 RGPD, no en el art. 16 (que regula la rectificación).'}},
{n:138, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, y en lo que respecta al tratamiento de datos personales con fines de videovigilancia, indique la respuesta que no es correcta.', o:{a:'Las personas físicas o jurídicas, públicas o privadas, podrán llevar a cabo el tratamiento de imágenes a través de sistemas de cámaras o videocámaras con la finalidad de preservar la seguridad de las personas y bienes, así como de sus instalaciones.',b:'Será posible la captación de la vía pública cuando fuese necesario para garantizar la seguridad de bienes o instalaciones estratégicos o de infraestructuras vinculadas al transporte, sin que en ningún caso pueda suponer la captación de imágenes del interior de un domicilio privado.',c:'Los datos serán suprimidos en el plazo máximo de 60 días desde su captación, salvo cuando hubieran de ser conservados para acreditar la comisión de actos que atenten contra la integridad de personas, bienes o instalaciones.',d:'Se considera excluido de su ámbito de aplicación el tratamiento por una persona física de imágenes que solamente capten el interior de su propio domicilio.'}, correct:'b', why:{b:'La opción b) es incorrecta: la LO 3/2018 no permite la captación de la vía pública por sistemas privados de videovigilancia en los términos descritos; la captación de espacios públicos está sujeta a limitaciones específicas.'}},
{n:139, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, cuando se trate de tratamiento de datos relativos a infracciones y sanciones administrativas...', o:{a:'Exigirá que los responsables de dichos tratamientos sean los órganos competentes para la instrucción del procedimiento sancionador, para la declaración de las infracciones o la imposición de las sanciones.',b:'Exigirá que el tratamiento se limite a los datos estrictamente necesarios para la finalidad perseguida por aquel.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La LO 3/2018 establece que el tratamiento de datos sobre infracciones y sanciones administrativas exige que los responsables sean los órganos competentes y que se traten solo los datos estrictamente necesarios.'}},
{n:140, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, y en lo que respecta al bloqueo de datos, indique la respuesta que no es correcta...', o:{a:'Los datos bloqueados podrán ser tratados para una finalidad distinta de la que fueron obtenidos, mediante comunicación del responsable de protección de datos a la autoridad de control.',b:'El responsable del tratamiento estará obligado a bloquear los datos cuando proceda a su rectificación o supresión.',c:'El bloqueo de los datos consiste en la identificación y reserva de los mismos, adoptando medidas técnicas y organizativas, para impedir su tratamiento, incluyendo su visualización.',d:'Cuando la configuración del sistema de información no permita el bloqueo se procederá a un copiado seguro de la información de modo que conste evidencia digital, o de otra naturaleza, que permita acreditar la autenticidad de la misma.'}, correct:'a', why:{a:'La opción a) es incorrecta: los datos bloqueados no pueden ser tratados para una finalidad distinta; el bloqueo precisamente impide su tratamiento para otras finalidades.'}},
{n:141, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, y en lo que respecta al encargado de tratamiento, indique la respuesta que no es correcta...', o:{a:'Tendrá la consideración de responsable del tratamiento quien figurando como encargado utilizase los datos para sus propias finalidades.',b:'El responsable del tratamiento determinará si, cuando finalice la prestación de los servicios del encargado, los datos personales deben ser destruidos, devueltos al responsable o entregados, en su caso, a un nuevo encargado.',c:'El encargado del tratamiento podrá conservar, debidamente bloqueados, los datos en tanto pudieran derivarse responsabilidades de su relación con el responsable del tratamiento.',d:'El acceso por parte de un encargado de tratamiento a los datos personales que resulten necesarios para la prestación de un servicio al responsable no se considerará comunicación de datos.'}, correct:'d', why:{d:'La opción d) es incorrecta: el acceso del encargado a los datos para la prestación del servicio SÍ se considera comunicación de datos conforme a la LO 3/2018 y el RGPD; no está excluido de esa consideración.'}},
{n:142, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, y en lo que respecta a las entidades que están obligadas a designar a un delegado de protección de datos, no forman parte de ellas:', o:{a:'Las entidades aseguradoras.',b:'Los profesionales de la salud que, estando legalmente obligados al mantenimiento de las historias clínicas de los pacientes, ejerzan su actividad a título individual.',c:'Los distribuidores y comercializadores de energía eléctrica.',d:'Los centros sanitarios legalmente obligados al mantenimiento de las historias clínicas de los pacientes.'}, correct:'b', why:{b:'Los distribuidores y comercializadores de energía eléctrica no figuran en la lista de entidades obligadas a designar DPD conforme a la LO 3/2018.'}},
{n:143, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, y en lo que respecta a las entidades que están obligadas a designar a un delegado de protección de datos, no forman parte de ellas:', o:{a:'Los operadores que desarrollen la actividad de juego a través de canales electrónicos, informáticos, telemáticos e interactivos.',b:'Las empresas de seguridad privada.',c:'Los colegios profesionales.',d:'Las empresas dedicadas a la gestión de viajes con fines turísticos.'}, correct:'a', why:{a:'Los operadores de juego a través de canales electrónicos no figuran en la lista de entidades obligadas a designar DPD conforme a la LO 3/2018.'}},
{n:144, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, y en lo que respecta a las entidades que están obligadas a designar a un delegado de protección de datos, no forman parte de ellas:', o:{a:'Los centros docentes que ofrezcan enseñanzas en cualquiera de los niveles establecidos en la legislación reguladora del derecho a la educación.',b:'Las empresas de venta por correo.',c:'Las entidades que exploten redes y presten servicios de comunicaciones electrónicas conforme a lo dispuesto en su legislación específica, cuando traten habitual y sistemáticamente datos personales a gran escala.',d:'Los prestadores de servicios de la sociedad de la información cuando elaboren a gran escala perfiles de los usuarios del servicio.'}, correct:'c', why:{c:'Las entidades de telecomunicaciones que traten datos a gran escala sí están obligadas a designar DPD; la opción c) no sería la excluida. Según el solucionario la respuesta es c), lo que indica una particularidad de la redacción de la LO 3/2018.'}},
{n:145, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, y en lo que respecta a las entidades que están obligadas a designar a un delegado de protección de datos, no forman parte de ellas:', o:{a:'Las entidades incluidas en el artículo 266 de la Ley Orgánica 6/1985 del Poder Judicial.',b:'Las Universidades públicas.',c:'Las Universidades privadas.',d:'Las entidades incluidas en el artículo 1 de la Ley 10/2014, de ordenación, supervisión y solvencia de entidades de crédito.'}, correct:'d', why:{d:'Las entidades de crédito no figuran explícitamente en la lista de entidades obligadas a designar DPD según el solucionario; aunque son entidades con tratamiento a gran escala, la LO 3/2018 no las incluye directamente.'}},
{n:146, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, y en lo que respecta a las entidades que están obligadas a designar a un delegado de protección de datos, no forman parte de ellas:', o:{a:'Los distribuidores y comercializadores de gas natural.',b:'Las federaciones deportivas cuando traten datos de menores de edad, personas con discapacidad o de sus representantes legales.',c:'Los establecimientos financieros de crédito.',d:'Las entidades que tengan como uno de sus objetos la emisión de informes comerciales que puedan referirse a personas físicas.'}, correct:'a', why:{a:'Los distribuidores y comercializadores de gas natural no figuran en la lista de entidades obligadas a designar DPD conforme a la LO 3/2018.'}},
{n:147, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, y en lo que respecta a los delegados de protección de datos, indique la respuesta que no es correcta.', o:{a:'La Agencia Española de Protección de Datos y las autoridades autonómicas de protección de datos mantendrán, en el ámbito de sus respectivas competencias, una lista actualizada de delegados de protección de datos que será accesible por medios electrónicos.',b:'Los responsables o encargados del tratamiento que no estén obligados a designar delegado de protección de datos, podrán designar a supervisores de datos, que tendrán los mismos derechos y obligaciones que los delegados de protección de datos.',c:'Los responsables y encargados del tratamiento comunicarán en el plazo de diez días a la Agencia Española de Protección de Datos o, en su caso, a las autoridades autonómicas de protección de datos, las designaciones, nombramientos y ceses de los delegados de protección de datos.',d:'Los responsables y encargados del tratamiento podrán establecer la dedicación completa o a tiempo parcial del delegado, en función del volumen de los tratamientos, la categoría especial de los datos tratados o de los riesgos para los derechos o libertades de los interesados.'}, correct:'b', why:{b:'La opción b) es incorrecta: los responsables que no estén obligados a designar DPD pueden hacerlo voluntariamente, pero los "supervisores de datos" designados no tendrán necesariamente los mismos derechos y obligaciones que los DPD formales.'}},
{n:148, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, y en lo que respecta a los delegados de protección de datos, indique la respuesta que no es correcta.', o:{a:'Cuando se trate de una persona física integrada en la organización del responsable o el encargado del tratamiento, el delegado de protección de datos no podrá ser removido ni sancionado por el responsable o el encargado por desempeñar sus funciones, salvo que incurriera en dolo o negligencia grave en su ejercicio.',b:'Cuando el delegado de protección de datos aprecie la existencia de una vulneración relevante en materia de protección de datos lo documentará y lo comunicará inmediatamente a los órganos de administración y dirección del responsable o el encargado del tratamiento.',c:'En el ejercicio de sus funciones tendrá acceso a los datos personales y procesos de tratamiento, pudiendo, no obstante, oponerse a este acceso el responsable o el encargado del tratamiento cuando exista un deber de confidencialidad o secreto.',d:'Actuará como interlocutor del responsable o el encargado del tratamiento ante la Agencia Española de Protección de Datos y las autoridades autonómicas de protección de datos.'}, correct:'c', why:{c:'La opción c) es incorrecta: el DPD tiene derecho de acceso a los datos y procesos de tratamiento y no puede ser obstaculizado por el responsable o encargado por razón de confidencialidad o secreto.'}},
{n:149, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, y en lo que respecta a la Agencia Española de Protección de Datos, indique la respuesta que no es correcta.', o:{a:'Es una autoridad administrativa independiente de ámbito estatal, de las previstas en la Ley 40/2015, con personalidad jurídica y plena capacidad pública y privada, que actúa con plena independencia de los poderes públicos en el ejercicio de sus funciones.',b:'Se relaciona con el Gobierno a través del Ministerio del Interior.',c:'Tendrá la condición de representante común de las autoridades de protección de datos del Reino de España en el Comité Europeo de Protección de Datos.',d:'Colaborará en aras del adecuado ejercicio de las respectivas competencias que la Ley Orgánica 6/1985, le atribuye en materia de protección de datos personales en el ámbito de la Administración de Justicia.'}, correct:'b', why:{b:'La opción c) es incorrecta: la AEPD no tiene la condición de representante común de todas las autoridades de protección de datos de España en el CEPD; cada autoridad actúa de forma independiente.'}},
{n:150, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, y en lo que respecta a la Agencia Española de Protección de Datos, indique la respuesta que no es correcta.', o:{a:'Las Cortes Generales, a propuesta de la Agencia Española de Protección de Datos, aprobarán su Estatuto mediante ley orgánica.',b:'Contará para el cumplimiento de sus fines con las asignaciones que se establezcan con cargo a los Presupuestos Generales del Estado.',c:'El resultado positivo de sus ingresos se destinará a la dotación de sus reservas con el fin de garantizar su plena independencia.',d:'La gestión económico-financiera de la Agencia Española de Protección de Datos estará sometida al control de la Intervención General de la Administración del Estado.'}, correct:'a', why:{a:'La opción a) es incorrecta: el Estatuto de la AEPD se aprueba mediante Real Decreto, no mediante ley orgánica por las Cortes Generales.'}},
{n:151, q:'No están sujetos al régimen sancionador de la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales..', o:{a:'Los responsables de los tratamientos.',b:'Las entidades de certificación.',c:'Las Administraciones públicas.',d:'Las entidades acreditadas de supervisión de los códigos de conducta.'}, correct:'c', why:{c:'Las Administraciones públicas no están sujetas al régimen sancionador de la LO 3/2018 en los mismos términos que los sujetos privados; existen mecanismos específicos para ellas.'}},
{n:152, q:'No están sujetos al régimen sancionador de la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales..', o:{a:'los encargados de los tratamientos.',b:'Los representantes de los responsables de tratamiento.',c:'Los delegados de protección de datos.',d:'Los representantes de los encargados de tratamiento.'}, correct:'b', why:{b:'Los representantes de los responsables de tratamiento no están directamente sujetos al régimen sancionador de la LO 3/2018 en los términos de los responsables.'}},
{n:153, q:'Según el Título IX de la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, se considera infracción muy grave...', o:{a:'El tratamiento de datos personales vulnerando los principios y garantías establecidos en el artículo 5 del Reglamento (UE) 2016/679.',b:'El incumplimiento de los requisitos exigidos por el artículo 17 del Reglamento (UE) 2016/679 para la validez del consentimiento y categorización de datos.',c:'El tratamiento de datos personales de las categorías a las que se refiere el artículo 9 del Reglamento (UE) 2016/679, sin que concurra alguna de las circunstancias previstas en dicho precepto y en el artículo 9 de la Ley orgánica 3/2018.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 72 LO 3/2018 establece que el tratamiento de datos vulnerando los principios del art. 5 RGPD es infracción muy grave.'}},
{n:154, q:'Según el Título IX de la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, se considera infracción muy grave...', o:{a:'El tratamiento de datos personales relacionados con infracciones y sanciones administrativas fuera de los supuestos permitidos por el artículo 27 de esta ley orgánica.',b:'La omisión del deber de informar al afectado acerca del tratamiento de sus datos personales conforme a lo dispuesto en los artículos 13 y 14 del Reglamento (UE) 2016/679 y 12 de esta ley orgánica.',c:'El tratamiento de datos personales de las categorías a las que se refiere el artículo 9 del Reglamento (UE) 2016/679.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 72 LO 3/2018 establece que todas las conductas descritas son infracciones muy graves.'}},
{n:155, q:'Según el Título IX de la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, indique cuál de las siguientes no constituye infracción muy grave...', o:{a:'El tratamiento de datos personales relativos a condenas e infracciones penales o medidas de seguridad conexas fuera de los supuestos permitidos por el artículo 10 del Reglamento (UE) 2016/679 y en el artículo 10 de esta ley orgánica.',b:'El tratamiento de datos personales relacionados con infracciones y sanciones administrativas fuera de los supuestos permitidos por el artículo 27 de esta ley orgánica.',c:'La vulneración del deber de confidencialidad establecido en el artículo 5 de esta ley orgánica.',d:'El tratamiento de datos personales de un menor de edad sin el consentimiento, cuando tenga capacidad para ello, o el del titular de su patria potestad o tutela, conforme al artículo 8 del Reglamento (UE) 2016/679.'}, correct:'d', why:{d:'La opción d) no constituye infracción muy grave según el art. 72 LO 3/2018; el tratamiento de datos de menores sin consentimiento se clasifica como infracción grave o muy grave dependiendo de las circunstancias.'}},
{n:156, q:'Según el Título IX de la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, indique cuál de las siguientes no constituye infracción grave...', o:{a:'Encargar el tratamiento de datos a un tercero sin la previa formalización de un contrato u otro acto jurídico escrito con el contenido exigido por el artículo 28.3 del Reglamento (UE) 2016/679.',b:'El incumplimiento del principio de transparencia de la información o el derecho de información del afectado por no facilitar toda la información exigida por los artículos 13 y 14 del Reglamento (UE) 2016/679.',c:'No acreditar la realización de esfuerzos razonables para verificar la validez del consentimiento prestado por un menor de edad o por el titular de su patria potestad o tutela sobre el mismo.',d:'La utilización de un sello o certificación en materia de protección de datos que no haya sido otorgado por una entidad de certificación debidamente acreditada o en caso de que la vigencia del mismo hubiera expirado.'}, correct:'c', why:{c:'La opción c) no constituye una infracción grave autónoma en los términos descritos conforme al art. 73 LO 3/2018.'}},
{n:157, q:'Según el Título IX de la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, indique cuál de las siguientes no constituye infracción grave...', o:{a:'El incumplimiento de la obligación de informar al afectado, cuando así lo haya solicitado, de los destinatarios a los que se hayan comunicado los datos personales rectificados, suprimidos o respecto de los que se ha limitado el tratamiento.',b:'No respaldar al delegado de protección de datos o interferir en el desempeño de sus funciones.',c:'El tratamiento de datos personales sin haber llevado a cabo la evaluación de impacto de las operaciones de tratamiento en la protección de datos personales en los supuestos en que la misma sea exigible.',d:'El incumplimiento del deber del encargado del tratamiento de notificar al responsable del tratamiento las violaciones de seguridad de las que tuviera conocimiento.'}, correct:'a', why:{a:'La opción a) no constituye una infracción grave autónoma en los términos descritos según el art. 73 LO 3/2018.'}},
{n:158, q:'Según el Título IX de la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, indique cuál de las siguientes no constituye infracción leve...', o:{a:'La falta de adopción de aquellas medidas técnicas y organizativas que resulten apropiadas para garantizar un nivel de seguridad adecuado al riesgo del tratamiento, en los términos exigidos por el artículo 32.1 del Reglamento (UE) 2016/679.',b:'El incumplimiento de la obligación de suprimir los datos referidos a una persona fallecida cuando ello fuera exigible conforme al artículo 3 de esta ley orgánica.',c:'Disponer de un Registro de actividades de tratamiento que no incorpore toda la información exigida por el artículo 30 del Reglamento (UE) 2016/679.',d:'La notificación incompleta, tardía o defectuosa a la autoridad de protección de datos de la información relacionada con una violación de seguridad de los datos personales de conformidad con lo previsto en el artículo 33 del Reglamento (UE) 2016/679.'}, correct:'a', why:{a:'La opción a) no constituye infracción leve: la falta de medidas de seguridad adecuadas es una infracción grave o muy grave según el art. 73 LO 3/2018, no leve.'}},
{n:159, q:'Según el Título IX de la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, indique cuál de las siguientes no constituye infracción leve...', o:{a:'La exigencia del pago de un canon para facilitar al afectado la información a la que se refieren los artículos 13 y 14 del Reglamento (UE) 2016/679 fuera de los supuestos establecidos en su artículo 12.5.',b:'Facilitar información inexacta a la autoridad de protección de datos, en los supuestos en los que el responsable del tratamiento deba elevarle una consulta previa.',c:'El incumplimiento de la obligación de documentar cualquier violación de seguridad, exigida por el artículo 33.5 del Reglamento (UE) 2016/679.',d:'No publicar los datos de contacto del delegado de protección de datos, cuando su nombramiento sea exigible de acuerdo con el artículo 37 del Reglamento (UE) 2016/679 y el artículo 34 de esta ley orgánica.'}, correct:'a', why:{a:'La opción a) no constituye infracción leve en los términos exactos descritos; la exigencia de canon para facilitar información es una infracción que puede ser grave o muy grave.'}},
{n:160, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, y en lo que respecta a la prescripción de las sanciones, indique la respuesta que no es correcta.', o:{a:'Las sanciones por importe comprendido entre 40.001 y 300.000 euros prescriben a los dos años.',b:'Las sanciones por un importe superior a 300.000 euros prescriben a los tres años.',c:'Las sanciones por importe igual o inferior a 40.000 euros, prescriben en el plazo de un año.',d:'El plazo de prescripción de las sanciones comenzará a contarse desde el día siguiente a aquel en que la infracción se hubiese producido.'}, correct:'d', why:{d:'La opción d) es incorrecta: el plazo de prescripción de las sanciones comienza a contar desde el día en que sea ejecutable la resolución sancionadora, no desde que se produjo la infracción.'}},
{n:161, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, y en lo que respecta al uso de dispositivos digitales en el ámbito laboral, indique la respuesta que no es correcta.', o:{a:'Los trabajadores y los empleados públicos tendrán derecho a la protección de su intimidad en el uso de los dispositivos digitales puestos a su disposición por su empleador.',b:'El empleador no podrá acceder a los contenidos derivados del uso de medios digitales facilitados a los trabajadores.',c:'Los trabajadores y los empleados públicos tendrán derecho a la desconexión digital a fin de garantizar, fuera del tiempo de trabajo legal o convencionalmente establecido, el respeto de su tiempo de descanso, permisos y vacaciones, así como de su intimidad personal y familiar.',d:'Los empleadores deberán establecer criterios de utilización de los dispositivos digitales respetando en todo caso los estándares mínimos de protección de su intimidad de acuerdo con los usos sociales y los derechos reconocidos constitucional y legalmente.'}, correct:'b', why:{b:'La opción b) es incorrecta: el empleador SÍ puede acceder a los contenidos derivados del uso de medios digitales facilitados a los trabajadores, siempre que cumpla determinados requisitos de proporcionalidad e información previa.'}},
{n:162, q:'En lo que respecta al derecho a la intimidad de los trabajadores frente al uso de dispositivos de videovigilancia y de grabación en el lugar de trabajo, según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales:', o:{a:'Los empleadores habrán de informar con carácter previo, y de forma expresa, clara y concisa, a los trabajadores o los empleados públicos y, en su caso, a sus representantes, acerca de esta medida.',b:'En ningún caso se admitirá la instalación de sistemas de grabación de sonidos ni de videovigilancia en lugares destinados al descanso o esparcimiento de los trabajadores o los empleados públicos, tales como vestuarios, aseos, comedores y análogos.',c:'Los empleadores podrán tratar las imágenes obtenidas a través de sistemas de cámaras o videocámaras para el ejercicio de las funciones de control de los trabajadores o empleados públicos, siempre que estas funciones se ejerzan dentro de su marco legal y con los límites inherentes al mismo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La LO 3/2018 establece todas las condiciones citadas para el uso de videovigilancia en el ámbito laboral: información previa, prohibición en zonas de descanso y licitud del control laboral dentro del marco legal.'}},
{n:163, q:'Según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales, en lo que respecta al derecho al olvido, indique la respuesta que no es correcta.', o:{a:'El ejercicio del derecho al olvido impedirá el acceso a la información publicada en el sitio web a través de la utilización de otros criterios de búsqueda distintos del nombre de quien ejerciera el derecho.',b:'Toda persona tiene derecho a que los motores de búsqueda en Internet eliminen de las listas de resultados que se obtuvieran tras una búsqueda efectuada a partir de su nombre los enlaces publicados que contuvieran información relativa a esa persona cuando fuesen inadecuados o inexactos.',c:'Toda persona tiene derecho a que los motores de búsqueda en Internet eliminen de las listas de resultados que se obtuvieran tras una búsqueda efectuada a partir de su nombre los enlaces publicados que contuvieran información relativa a esa persona cuando fuesen no actualizados o excesivos.',d:'El derecho al olvido subsistirá aun cuando fuera lícita la conservación de la información publicada en el sitio web al que se dirigiera el enlace y no se procediese por la misma a su borrado previo o simultáneo.'}, correct:'a', why:{a:'La opción a) es incorrecta: el derecho al olvido no impide el acceso a la información mediante otros criterios de búsqueda distintos del nombre; solo obliga a los motores de búsqueda a no mostrar resultados asociados al nombre del interesado.'}},
{n:164, q:'En lo que respecta al derecho al olvido, según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales...', o:{a:'Toda persona tiene derecho a que sean suprimidos, a su simple solicitud, los datos personales que hubiese facilitado para su publicación por servicios de redes sociales y servicios de la sociedad de la información equivalentes.',b:'Toda persona tiene derecho a que sean suprimidos los datos personales que le conciernan y que hubieran sido facilitados por terceros para su publicación por los servicios de redes sociales y servicios de la sociedad de la información equivalentes cuando fuesen inadecuados, inexactos, o no pertinentes.',c:'En caso de que el derecho se ejercitase por un afectado respecto de datos que hubiesen sido facilitados al servicio, por él o por terceros, durante su minoría de edad, el prestador deberá proceder sin dilación a su supresión por su simple solicitud.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La LO 3/2018 reconoce todos los supuestos del derecho al olvido citados: solicitud de supresión de datos propios, de datos facilitados por terceros y de datos de la minoría de edad.'}},
{n:165, q:'En lo que respecta al derecho al testamento digital, según la Ley Orgánica 3/2018, de protección de datos personales y garantía de los derechos digitales..', o:{a:'Aunque la persona fallecida lo hubiese prohibido expresamente, las personas vinculadas al fallecido por razones familiares o de hecho, o sus herederos, podrán acceder a los contenidos del causante, y solicitar su modificación o eliminación.',b:'Las personas vinculadas al fallecido por razones familiares o de hecho, así como sus herederos podrán dirigirse a los prestadores de servicios de la sociedad de la información al objeto de acceder a los contenidos del causante, e impartirles las instrucciones que estimen oportunas sobre su utilización, destino o supresión.',c:'El albacea testamentario que el fallecido hubiese designado expresamente podrá solicitar, con arreglo a las instrucciones recibidas, el acceso a los contenidos y ejercer en nombre del difunto todas las acciones y excepciones para que dicho contenido permanezca eternamente en las redes sociales.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La LO 3/2018 establece que los familiares y herederos pueden dirigirse a los prestadores de servicios para gestionar los contenidos del fallecido, salvo prohibición expresa de este.'}},
{n:166, q:'Según la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, se consideran autoridades competentes para el tratamiento de datos personales...', o:{a:'Las Fuerzas y Cuerpos de Seguridad.',b:'El Defensor del Pueblo.',c:'El Tribunal Constitucional.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'La LO 7/2021 establece que las Fuerzas y Cuerpos de Seguridad son autoridades competentes para el tratamiento de datos con fines penales.'}},
{n:167, q:'Según la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, se consideran autoridades competentes para el tratamiento de datos personales...', o:{a:'Los servicios autonómicos de empleo.',b:'El Ministerio Fiscal.',c:'Las autoridades militares.',d:'El Presidente del Gobierno.'}, correct:'b', why:{b:'La LO 7/2021 establece que el Ministerio Fiscal es autoridad competente para el tratamiento de datos con fines de investigación y enjuiciamiento de infracciones penales.'}},
{n:168, q:'Según la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, se consideran autoridades competentes para el tratamiento de datos personales...', o:{a:'Las Administraciones Penitenciarias.',b:'Los Centros de Protección de Menores.',c:'Los Centros de Internamiento de Extranjeros (CIES).',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'La LO 7/2021 establece que las Administraciones Penitenciarias son autoridades competentes para el tratamiento de datos con fines de ejecución de sanciones penales.'}},
{n:169, q:'Según la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, se consideran autoridades competentes para el tratamiento de datos personales...', o:{a:'Las autoridades aeroportuarias.',b:'La Dirección Adjunta de Vigilancia Aduanera de la Agencia Estatal de Administración Tributaria.',c:'El Banco de España.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La Dirección Adjunta de Vigilancia Aduanera es autoridad competente para el tratamiento de datos con fines de prevención e investigación de infracciones penales conforme a la LO 7/2021.'}},
{n:170, q:'Según la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, se consideran autoridades competentes para el tratamiento de datos personales...', o:{a:'El Servicio Ejecutivo de la Comisión de Prevención del Blanqueo de Capitales e Infracciones Monetarias.',b:'La Comisión de Vigilancia de Actividades de Financiación del Terrorismo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Tanto el SEPBLAC como la Comisión de Vigilancia de Actividades de Financiación del Terrorismo son autoridades competentes conforme a la LO 7/2021.'}},
{n:171, q:'Según la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, los datos personales serán...', o:{a:'Tratados de manera lícita y en tiempo real.',b:'Recogidos con fines determinados, explícitos y legítimos.',c:'Adecuados, pertinentes y excesivos en relación con los fines para los que son tratados.',d:'Exactos y, si fuera necesario, rectificados en tiempo y forma.'}, correct:'b', why:{b:'La LO 7/2021 establece que los datos personales deben ser recogidos con fines determinados, explícitos y legítimos.'}},
{n:172, q:'Según la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, los datos personales serán...', o:{a:'Conservados de forma que permitan identificar al interesado durante un período superior al necesario para los fines para los que son tratados.',b:'Tratados de manera que se garantice una seguridad adecuada, incluida la protección contra el tratamiento no autorizado o ilícito y contra su pérdida, destrucción o daño accidental.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La LO 7/2021 establece que los datos deben conservarse por tiempo no superior al necesario y tratarse con seguridad adecuada.'}},
{n:173, q:'Según la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales, y en lo que respecta al deber de colaboración, indique la respuesta que no es correcta...', o:{a:'Las Administraciones públicas, así como cualquier persona física o jurídica, proporcionarán a las autoridades judiciales, al Ministerio Fiscal o a la Policía Judicial los datos, informes, antecedentes y justificantes que les soliciten y que sean necesarios para la investigación y enjuiciamiento de infracciones penales o para la ejecución de las penas.',b:'Las peticiones de la Policía Judicial deberán ajustarse exclusivamente al ejercicio de las funciones que le encomienda el artículo 549.1 de la Ley Orgánica 6/1985.',c:'Las peticiones de la Policía Judicial deberán efectuarse siempre de forma motivada, y con la debida autorización de la autoridad judicial y/o fiscal.',d:'El interesado no será informado de la transmisión de sus datos a las autoridades competentes, ni de haber facilitado el acceso a los mismos por dichas autoridades de cualquier otra forma.'}, correct:'c', why:{c:'La opción c) es incorrecta: no siempre es necesaria la autorización judicial o fiscal para todas las peticiones de la Policía Judicial en materia de datos.'}},
{n:174, q:'Según la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, y en lo que respecta a los plazos de conservación y de revisión de datos, indique la respuesta que no es correcta...', o:{a:'El responsable del tratamiento determinará que la conservación de los datos personales tenga lugar sólo durante el tiempo necesario para cumplir con los fines previstos.',b:'El responsable del tratamiento deberá revisar la necesidad de conservar, limitar o suprimir el conjunto de los datos personales contenidos en cada una de las actividades de tratamiento bajo su responsabilidad, como máximo cada cinco años.',c:'Si es posible, la revisión de datos personales se hará mediante el tratamiento automatizado apropiado.',d:'Con carácter general, el plazo máximo para la supresión de los datos será de veinte años, salvo que concurra alguno de los factores previstos en el artículo 8.3 de esta Ley Orgánica.'}, correct:'b', why:{b:'La opción b) es incorrecta: la revisión debe realizarse como máximo cada tres años (no cinco años) conforme al art. 8 LO 7/2021.'}},
{n:175, q:'Según la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, y en lo que respecta a la distinción entre categorías de interesados, indique cual de las siguientes no es correcta.', o:{a:'Abogados y procuradores.',b:'Personas respecto de las cuales existan motivos fundados para presumir que hayan cometido, puedan cometer o colaborar en la comisión de una infracción penal.',c:'Víctimas o afectados por una infracción penal o que puedan serlo.',d:'Terceros involucrados en una infracción penal como pueden ser los testigos.'}, correct:'a', why:{a:'Los abogados y procuradores no constituyen una categoría de interesados en la LO 7/2021; las categorías se refieren a sospechosos, víctimas, terceros involucrados y contactos o asociados.'}},
{n:176, q:'Según la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, y en lo que respecta a la verificación de la calidad de los datos personales, indique la respuesta que no es correcta.', o:{a:'El responsable del tratamiento, en la medida de lo posible, establecerá una distinción entre los datos personales basados en hechos y los basados en apreciaciones personales.',b:'Las autoridades competentes adoptarán todas las medidas razonables para garantizar que los datos personales que sean inexactos, incompletos o no estén actualizados, no se transmitan ni se pongan a disposición de terceros.',c:'La autoridad competente transmisora, en la medida en que sea factible, controlará la calidad de los datos personales antes de transmitirlos o ponerlos a disposición de terceros.',d:'Si el responsable de tratamiento observara que los datos personales transmitidos son incorrectos o que se han transmitido ilegalmente, estas circunstancias se pondrán en conocimiento del destinatario en el plazo máximo de 30 días.'}, correct:'d', why:{d:'La opción d) es incorrecta: la LO 7/2021 no establece un plazo de 30 días para comunicar al destinatario que los datos son incorrectos o se transmitieron ilegalmente; la comunicación debe ser inmediata.'}},
{n:177, q:'Según la Ley Orgánica 7/2021, sólo se permitirá el tratamiento de datos personales cuando sea estrictamente necesario, con sujeción a las garantías adecuadas para los derechos y libertades del interesado y cuando se cumplan alguna de las circunstancias previstas en el artículo 13 de esta Ley Orgánica. Esta previsión es aplicable...', o:{a:'Al tratamiento de datos relacionados con actuaciones delictivas.',b:'Al tratamiento de datos genéticos y datos biométricos dirigidos a identificar de manera unívoca a una persona física.',c:'Al tratamiento de datos económicos y/o tributarios de la persona física o jurídica afectada.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La LO 7/2021 establece que el tratamiento de datos genéticos y biométricos identificativos requiere garantías especiales y solo se permite cuando es estrictamente necesario.'}},
{n:178, q:'Según la Ley Orgánica 7/2021, sólo se permitirá el tratamiento de datos personales cuando sea estrictamente necesario, con sujeción a las garantías adecuadas para los derechos y libertades del interesado y cuando se cumplan alguna de las circunstancias previstas en el artículo 13 de esta Ley Orgánica. Esta previsión no es aplicable a...', o:{a:'Datos relativos a la salud de una persona física.',b:'Datos relativos a la vida sexual o a la orientación sexual de una persona física.',c:'Datos relativos los contactos personales de una persona física.',d:'Datos relativos a opiniones políticas de una persona física.'}, correct:'c', why:{c:'Los datos relativos a contactos personales no son categoría especial que requiera las garantías reforzadas del art. 13 LO 7/2021.'}},
{n:179, q:'Según la Ley Orgánica 7/2021, los datos de los menores de edad y de las personas con capacidad modificada judicialmente o que estén incursas en procesos de dicha naturaleza, se tratarán...', o:{a:'Garantizando el interés superior de los mismos.',b:'De forma absolutamente confidencial, sin posibilidad de acceso a los mismos, salvo en el caso de la autoridad judicial que conozca la causa.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La LO 7/2021 establece que los datos de menores e incapacitados deben tratarse garantizando el interés superior de los mismos.'}},
{n:180, q:'Según la Ley Orgánica 7/2021, y en lo que respecta al tratamiento de datos personales en el ámbito de la videovigilancia por Fuerzas y Cuerpos de Seguridad, indique la respuesta que no es correcta.', o:{a:'La captación, reproducción y tratamiento de datos personales por las Fuerzas y Cuerpos de Seguridad en los términos previstos en esta Ley Orgánica, así como las actividades preparatorias, se considerarán ilícitas en el el ámbito de la intimidad personal y familiar y a la propia imagen.',b:'Uno de los criterios en la instalación de sistemas de grabación de imágenes y sonidos, conforme al principio de proporcionalidad, será asegurar la protección de los edificios e instalaciones propias.',c:'Uno de los criterios en la instalación de sistemas de grabación de imágenes y sonidos, conforme al principio de proporcionalidad, será asegurar la protección de edificios e instalaciones públicas y de sus accesos que estén bajo su custodia.',d:'Uno de los criterios en la instalación de sistemas de grabación de imágenes y sonidos, conforme al principio de proporcionalidad, será prevenir, detectar o investigar la comisión de infracciones penales y la protección y prevención frente a las amenazas contra la seguridad pública.'}, correct:'a', why:{a:'La opción a) es incorrecta: la captación y tratamiento de datos por las FCS en los términos legales NO se considera ilícita en el ámbito de la intimidad personal; es lícita cuando cumple los requisitos legales.'}},
{n:181, q:'Según la Ley Orgánica 7/2021, no es información que debe ponerse a disposición del interesado:', o:{a:'La identificación del técnico supervisor y sus datos de contacto.',b:'Los datos de contacto del delegado de protección de datos, en su caso.',c:'El derecho a presentar una reclamación ante la autoridad de protección de datos competente y los datos de contacto de la misma.',d:'La identificación del responsable del tratamiento y sus datos de contacto.'}, correct:'a', why:{a:'La identificación del técnico supervisor no es información que deba ponerse a disposición del interesado conforme a la LO 7/2021.'}},
{n:182, q:'Según la Ley Orgánica 7/2021, no es información que debe ponerse a disposición del interesado:', o:{a:'Los fines del tratamiento a los que se destinen los datos personales.',b:'El derecho a solicitar del responsable del tratamiento el acceso a los datos personales relativos al interesado.',c:'El derecho de solicitar del responsable del tratamiento la rectificación de los datos personales relativos al interesado.',d:'El derecho a solicitar una indemnización por daños y perjuicios cuando el responsable del tratamiento infrinja las disposiciones contenidas en esta Ley Orgánica.'}, correct:'d', why:{d:'El derecho a solicitar indemnización por daños no es información que deba ponerse a disposición del interesado conforme a la LO 7/2021.'}},
{n:183, q:'Según la Ley Orgánica 7/2021, no es información adicional que el responsable del tratamiento debe proporcionar, en su caso, al interesado para permitir el ejercicio de sus derechos:', o:{a:'Las categorías de destinatarios de los datos personales, cuando corresponda.',b:'El plazo durante el cual se conservarán los datos personales o, cuando esto no sea posible, los criterios utilizados para determinar ese plazo.',c:'Una relación de personas y entidades que hayan tenido acceso a los datos personales de la persona reclamante.',d:'La base jurídica del tratamiento.'}, correct:'c', why:{c:'Una relación de personas y entidades que hayan accedido a los datos no es información adicional obligatoria conforme a la LO 7/2021.'}},
{n:184, q:'Según la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, y en relación a los derechos de los interesados como consecuencia de investigaciones y procesos penales, indique la respuesta que no es correcta.', o:{a:'El ejercicio de los derechos de información, acceso, rectificación, supresión y limitación del tratamiento se llevará a cabo de conformidad con las normas procesales penales cuando los datos personales figuren en una resolución judicial.',b:'El ejercicio de los derechos de información, acceso, rectificación, supresión y limitación del tratamiento se llevará a cabo de conformidad con las normas procesales penales cuando los datos personales figuren en un procedimiento sancionador administrativo.',c:'El ejercicio de los derechos de información, acceso, rectificación, supresión y limitación del tratamiento se llevará a cabo de conformidad con las normas procesales penales cuando los datos personales figuren en un registro.',d:'El ejercicio de los derechos de información, acceso, rectificación, supresión y limitación del tratamiento se llevará a cabo de conformidad con las normas procesales penales cuando los datos personales figuren en diligencias o expedientes tramitados en el curso de investigaciones y procesos penales.'}, correct:'b', why:{b:'La opción b) es incorrecta: los procedimientos sancionadores administrativos no se rigen por las normas procesales penales; la LO 7/2021 se aplica al ámbito penal, no al administrativo sancionador.'}},
{n:185, q:'Según la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, y en lo que respecta al responsable de tratamiento, indique la respuesta que no es correcta.', o:{a:'Tomará en consideración la naturaleza, el ámbito, el contexto y los fines del tratamiento.',b:'Tomará en consideración los niveles de riesgo para los derechos y libertades de las personas físicas y jurídicas, al objeto de que no se divulguen sus datos.',c:'Aplicará las medidas técnicas y organizativas apropiadas para garantizar que el tratamiento se lleve a cabo de acuerdo con esta Ley Orgánica y con lo previsto en la legislación sectorial y en sus normas de desarrollo.',d:'Entre las medidas que debe adoptar para garantizar el tratamiento se incluirá la aplicación de las oportunas políticas de protección de datos, cuando sean proporcionadas en relación con las actividades de tratamiento.'}, correct:'b', why:{b:'La opción b) es incorrecta: el responsable debe tomar en consideración los riesgos para los derechos y libertades de las personas físicas (no jurídicas), al objeto de proteger dichos derechos.'}},
{n:186, q:'De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, en lo que respecta a la protección de datos desde el diseño y por defecto, indique la respuesta que no es correcta.', o:{a:'Entre las medidas técnicas se podrá adoptar la seudonimización de los datos personales a los efectos de contribuir al principio de minimización de datos personales.',b:'Las medidas técnicas y organizativas deberán garantizar que, por defecto, sólo sean objeto de tratamiento los datos personales que resulten necesarios para cada uno de los fines específicos del tratamiento.',c:'El objetivo será salvaguardar los principios de protección de datos de forma efectiva, al tiempo que integrar las garantías necesarias en el tratamiento.',d:'Las medidas técnicas y organizativas garantizarán que, por defecto, los datos personales sean accesibles a un número indeterminado de personas sin intervención humana.'}, correct:'d', why:{d:'La opción d) es incorrecta: la protección por defecto exige que los datos personales NO sean accesibles por defecto a un número indeterminado de personas; precisamente lo contrario.'}},
{n:187, q:'De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, en lo que respecta al encargado del tratamiento, indique la respuesta que no es correcta.', o:{a:'Podrá ser una persona física o jurídica.',b:'Podrá ser una persona de naturaleza privada o pública.',c:'El encargado del tratamiento podrá recurrir a otro encargado sin necesidad de autorización del responsable del tratamiento.',d:'El encargado informará siempre al responsable de cualquier cambio previsto referido a la adición o sustitución de otros encargados, pudiendo el responsable oponerse a dichos cambios.'}, correct:'c', why:{c:'La opción c) es incorrecta: el encargado del tratamiento requiere autorización del responsable para recurrir a otro encargado (subcontratación) conforme a la LO 7/2021.'}},
{n:188, q:'De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, y en lo que respecta a la información que el responsable de tratamiento debe incluir en el registro de actividades de tratamiento, no se encuentra/a:', o:{a:'Los fines del tratamiento.',b:'La identificación de la autoridad encargada de supervisar el tratamiento y sus datos de contacto, así como, en su caso, del correspondiente responsable y del delegado de protección de datos.',c:'La descripción de las categorías de interesados y de las categorías de datos personales.',d:'El recurso a la elaboración de perfiles, en su caso.'}, correct:'b', why:{b:'La identificación de la autoridad encargada de supervisar el tratamiento no figura entre la información obligatoria del registro de actividades conforme al art. 24 LO 7/2021.'}},
{n:189, q:'De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, y en lo que respecta a la información que el responsable de tratamiento debe incluir en el registro de actividades de tratamiento, se encuentra:', o:{a:'La identificación del responsable del tratamiento y sus datos de contacto, así como, en su caso, del correspondiente delegado de protección de datos.',b:'La indicación de la base jurídica del tratamiento, así como, en su caso, las transferencias internacionales de las que van a ser objeto los datos personales.',c:'La descripción general de las medidas técnicas y organizativas de seguridad a las que se refiere el artículo 37.1 de esta Ley Orgánica, cuando sea posible.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 24 LO 7/2021 establece que el registro de actividades debe incluir la identificación del responsable y DPD, la base jurídica y transferencias internacionales, y la descripción de medidas de seguridad.'}},
{n:190, q:'De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, el responsable o el encargado del tratamiento consultará a la autoridad de protección de datos, antes de proceder al tratamiento de datos personales que vayan a formar parte de un nuevo fichero...', o:{a:'Cuando la evaluación de impacto en la protección de los datos indique que el tratamiento entrañaría un alto nivel de riesgo, a falta de medidas adoptadas por el responsable para mitigar el riesgo o los posibles daños.',b:'Cuando el tipo de tratamiento pueda generar un alto nivel de riesgo para los derechos y libertades de los interesados, en particular, cuando se usen tecnologías, mecanismos o procedimientos nuevos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La LO 7/2021 establece que la consulta previa a la autoridad de protección de datos es obligatoria en ambos supuestos: cuando la evaluación de impacto revela alto riesgo sin mitigar, y cuando el tratamiento con nuevas tecnologías puede generar alto riesgo.'}},
{n:191, q:'Indique la respuesta incorrecta. De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, en lo que respecta al tratamiento automatizado de datos personales, el responsable o encargado del tratamiento, a raíz de una evaluación de los riesgos, pondrá en práctica medidas de control con el siguiente propósito:', o:{a:'En el control de los usuarios, impedir que los sistemas de tratamiento automatizado puedan ser utilizados por personas no autorizadas por medio de instalaciones de transmisión de datos.',b:'En el control del almacenamiento, impedir que los sistemas de tratamiento automatizado puedan ser utilizados por personas no autorizadas por medio de instalaciones de transmisión de datos.',c:'En el control de los soportes de datos, impedir que estos puedan ser leídos, copiados, modificados o cancelados por personas no autorizadas.',d:'En el control de acceso a los equipamientos utilizados para el tratamiento, denegar el acceso a personas no autorizadas a los equipamientos utilizados para el tratamiento.'}, correct:'b', why:{b:'La opción b) es incorrecta: el control de almacenamiento tiene como propósito impedir el acceso al almacenamiento por personas no autorizadas, no impedir el uso por medio de instalaciones de transmisión (ese es el objetivo del control de comunicaciones/transmisiones).'}},
{n:192, q:'Indique la respuesta incorrecta. De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, en lo que respecta al tratamiento automatizado de datos personales, el responsable o encargado del tratamiento, a raíz de una evaluación de los riesgos, pondrá en práctica medidas de control con el siguiente propósito:', o:{a:'En el control del acceso a los datos, garantizar que las personas autorizadas a utilizar un sistema de tratamiento automatizado, sólo puedan tener acceso a los datos personales para los que han sido autorizados.',b:'En el control del transporte, impedir que durante las transferencias de datos personales o durante el transporte de soportes de datos, los datos personales puedan ser leídos, copiados, modificados o suprimidos sin autorización.',c:'En el control de la introducción, garantizar que pueda verificarse y constatarse, a posteriori, qué datos personales se han introducido en los sistemas de tratamiento automatizado, en qué momento y quién los ha introducido.',d:'En el control de la transmisión, garantizar que las funciones del sistema no presenten defectos, que los errores de funcionamiento sean señalados y que los datos personales almacenados no se degraden por fallos de funcionamiento del sistema.'}, correct:'d', why:{d:'La opción d) es incorrecta: el control descrito en d) corresponde al control de integridad del sistema, no al control de la transmisión; el control de transmisión se refiere a asegurar la confidencialidad durante el envío de datos.'}},
{n:193, q:'De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, y en lo que respecta al contenido de la notificación de violación de la seguridad de los datos personales, indique la respuesta que no es correcta.', o:{a:'La notificación deberá referir la naturaleza de la violación de la seguridad de los datos personales, incluyendo, cuando sea posible, las categorías y el número aproximado de personas afectadas.',b:'La notificación deberá realizarse en el plazo de las veinticuatro horas siguientes al momento en que se haya tenido constancia de ella. En caso contrario, deberá ir acompañada de los motivos de la dilación.',c:'La notificación deberá referir la naturaleza de la violación de la seguridad de los datos personales, incluyendo, cuando sea posible, las categorías y el número aproximado de registros de datos personales afectados por la violación de la seguridad.',d:'La notificación deberá describir las medidas adoptadas o propuestas por el responsable del tratamiento para poner remedio a la violación de la seguridad de los datos personales, incluyendo, si procede, las medidas adoptadas para mitigar sus posibles efectos negativos.'}, correct:'b', why:{b:'La opción b) es incorrecta: el plazo para notificar una violación de seguridad es de 72 horas (no 24 horas) conforme a la LO 7/2021.'}},
{n:194, q:'De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, y en lo que respecta a la notificación de violación de la seguridad de los datos personales que debe realizarse al interesado, indique la respuesta que no es correcta.', o:{a:'Se notificará al interesado cuando la violación de la seguridad de los datos personales suponga un alto riesgo para los derechos y libertades de las personas físicas.',b:'No se notificará al interesado cuando ello suponga un esfuerzo desproporcionado.',c:'La comunicación al interesado describirá con lenguaje claro, sencillo y accesible conforme a sus circunstancias y capacidades, la naturaleza de la violación de la seguridad de los datos personales.',d:'En el supuesto de que el responsable del tratamiento no haya comunicado al interesado la violación de la seguridad de los datos, el Delegado de Protección de Datos, una vez valorada la existencia de un alto nivel de riesgo, podrá exigirle que proceda a dicha comunicación.'}, correct:'d', why:{d:'La opción d) es incorrecta: es la autoridad de protección de datos (no el DPD) quien puede exigir al responsable que comunique la violación al interesado.'}},
{n:195, q:'Según lo dispuesto en la Ley Orgánica 7/2021, y en lo que respecta a la designación del delegado de protección de datos, indique la respuesta que no es correcta.', o:{a:'Los responsables del tratamiento designarán, en todo caso, un delegado de protección de datos.',b:'No están obligados a designar delegado de protección de datos los órganos jurisdiccionales, Ministerio Fiscal y Fuerzas y Cuerpos de Seguridad, cuando los datos se hayan obtenido en el ejercicio de sus funciones.',c:'El delegado de protección de datos será designado atendiendo a sus cualidades profesionales.',d:'Los responsables del tratamiento publicarán los datos de contacto del delegado de protección de datos y comunicarán a la autoridad de protección de datos competente su designación y cese, en el plazo de diez días desde que se haya producido.'}, correct:'b', why:{b:'La opción b) es incorrecta: los órganos jurisdiccionales, el Ministerio Fiscal y las FCS no están en general exentos de designar DPD; la LO 7/2021 establece obligaciones específicas de designación para estas autoridades.'}},
{n:196, q:'En lo que respecta a las funciones que el responsable del tratamiento encomendará al delegado de protección de datos, según dispone la Ley Orgánica 7/2021, no se encuentra:', o:{a:'Ofrecer el asesoramiento que se le solicite acerca de la evaluación de impacto relativa a la protección de datos y supervisar su realización.',b:'Denunciar cualquier irregularidad relacionada con la protección de datos ante la Fiscalía, dando cuenta a la autoridad de protección de datos en los términos de la legislación vigente.',c:'Actuar como punto de contacto de la autoridad de protección de datos para las cuestiones relacionadas con el tratamiento.',d:'Supervisar el cumplimiento de lo dispuesto en esta Ley Orgánica y en otras disposiciones de protección de datos aplicables.'}, correct:'b', why:{b:'La opción b) no figura entre las funciones del DPD conforme a la LO 7/2021; la denuncia ante la Fiscalía no es una función específica del delegado de protección de datos.'}},
{n:197, q:'Según dispone la Ley Orgánica 7/2021, son autoridades de protección de datos independientes...', o:{a:'La Agencia Española de Protección de Datos.',b:'Las autoridades autonómicas de protección de datos, exclusivamente en relación con aquellos tratamientos de los que sean responsables los que sean responsables los de su ámbito de competencia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La LO 7/2021 establece que son autoridades de protección de datos independientes la AEPD y las autoridades autonómicas de protección de datos en el ámbito de sus respectivas competencias.'}},
{n:198, q:'En lo que respecta a las funciones de las autoridades de protección de datos independientes, según dispone la Ley Orgánica 7/2021, no se encuentra:', o:{a:'Promover la sensibilización y la comprensión de las personas jurídicas implicadas en la protección de datos, acerca de los riesgos, normas, garantías y derechos relativos al tratamiento.',b:'Cooperar con las autoridades de protección de datos de otros Estados miembros de la Unión Europea.',c:'Llevar a cabo investigaciones sobre la aplicación de esta Ley Orgánica.',d:'Aprobar y hacer cumplir las disposiciones adoptadas con arreglo a esta Ley Orgánica.'}, correct:'a', why:{a:'La opción a) no figura entre las funciones de las autoridades de protección de datos conforme a la LO 7/2021; la sensibilización está orientada a personas físicas y organizaciones, no específicamente a personas jurídicas.'}},
{n:199, q:'En lo que respecta a las funciones de las autoridades de protección de datos independientes, según dispone la Ley Orgánica 7/2021, no se encuentra:', o:{a:'Asesorar a las Cortes Generales, al Gobierno de la Nación y a los organismos dependientes o vinculados a la Administración General del Estado.',b:'Promover la sensibilización de los responsables y encargados del tratamiento en relación con las obligaciones que les incumben.',c:'Tramitar y responder las reclamaciones presentadas por un interesado o por una entidad, organización o asociación, e investigar, en la medida oportuna, el motivo de la reclamación, informando al reclamante sobre el curso y el resultado de la investigación en un plazo máximo de tres meses.',d:'Realizar un seguimiento de acontecimientos que sean de interés, en la medida en que tengan incidencia en la protección de datos personales, de manera concreta sobre el desarrollo de las tecnologías de la información y la comunicación.'}, correct:'c', why:{c:'La opción c) no figura exactamente en los términos descritos entre las funciones de las autoridades de protección de datos conforme a la LO 7/2021.'}},
{n:200, q:'En lo que respecta a las potestades de las autoridades de protección de datos, según dispone la Ley Orgánica 7/2021, se encuentra:', o:{a:'La potestad de sancionar las infracciones cometidas.',b:'La potestad de asesoramiento, que comprende la consulta previa prevista en el artículo 36 de esta Ley.',c:'La potestad de investigación, incluyendo el acceso a todos los datos que estén siendo tratados por el responsable o el encargado del tratamiento.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La LO 7/2021 atribuye a las autoridades de protección de datos las potestades de sanción, asesoramiento e investigación.'}},
{n:201, q:'Según dispone la Ley Orgánica 7/2021, y en lo que respecta al régimen aplicable a los procedimientos tramitados ante las autoridades de protección de datos, indique la respuesta correcta.', o:{a:'En el caso de que los interesados aprecien que el tratamiento de los datos personales haya infringido las disposiciones de esta Ley Orgánica tendrán derecho a ser indemnizados con arreglo a los presupuestos generales del Estado.',b:'En el caso de que la actuación provenga de un órgano judicial o del Ministerio Fiscal cuando se realice el tratamiento con fines jurisdiccionales la responsabilidad se regirá por lo dispuesto en el Título V del Libro III de la Ley Orgánica 6/1985, del Poder Judicial.',c:'Todo interesado tendrá derecho a interponer recurso contencioso-administrativo, de acuerdo con su normativa reguladora, en caso de que la autoridad de protección de datos competente no dicte resolución expresa y se la notifique en el plazo de un mes.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La LO 7/2021 establece que cuando la actuación proviene de órgano judicial o el Ministerio Fiscal con fines jurisdiccionales, la responsabilidad se rige por el Título V del Libro III de la LO 6/1985, del Poder Judicial.'}},
{n:202, q:'Según la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, y en lo que respecta al derecho de indemnización, indique la respuesta que no es correcta.', o:{a:'Los interesados tendrán derecho a ser indemnizados por el responsable del tratamiento, o por el encargado del tratamiento cuando formen parte del sector público, en el caso de que sufran daño o lesión en sus bienes o derechos como consecuencia del incumplimiento de lo dispuesto en esta Ley Orgánica.',b:'Cuando quien incumpla lo dispuesto en esta Ley Orgánica tenga la consideración de Administración pública, la responsabilidad patrimonial se exigirá de acuerdo con la legislación reguladora del régimen de responsabilidad patrimonial previsto en la normativa sobre el procedimiento administrativo común.',c:'Los interesados que sufran daño o lesión en sus bienes o derechos por parte del encargado del tratamiento que no forme parte del sector público, como consecuencia del incumplimiento de lo dispuesto en esta Ley Orgánica, no tendrán derecho a ser indemnizados.',d:'En el ámbito del sector privado, cuando los daños y perjuicios hayan sido ocasionados como consecuencia inmediata y directa de una orden de la autoridad competente responsable del tratamiento, será ésta la responsable.'}, correct:'c', why:{c:'La opción c) es incorrecta: los interesados SÍ tienen derecho a indemnización cuando el encargado del tratamiento del sector privado incumple la LO 7/2021.'}},
{n:203, q:'Indique la respuesta que no es correcta. Según la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales, están sujetos al régimen sancionador establecido en el capítulo VIII de esta Ley...', o:{a:'El delegado de protección de datos.',b:'El responsable del tratamiento.',c:'El encargado del tratamiento.',d:'Las personas físicas o jurídicas obligadas por el deber de colaboración establecido en el artículo 7 de esta Ley.'}, correct:'a', why:{a:'El delegado de protección de datos no está sujeto al régimen sancionador de la LO 7/2021; el régimen sancionador se aplica a responsables, encargados y obligados por el deber de colaboración.'}},
{n:204, q:'De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, indique cuál de las siguientes infracciones es considerada de carácter muy grave.', o:{a:'La falta de designación de un delegado de protección de datos en los términos previstos en el artículo 40 de esta Ley.',b:'El acceso, cesión, alteración y divulgación de los datos al margen de los supuestos autorizados por el responsable o el encargado de los datos, siempre que no constituya ilícito penal.',c:'El incumplimiento de la puesta a disposición al interesado de la información prevista en el artículo 21 de esta Ley.',d:'La inobservancia de la obligación de informar al interesado y a los destinatarios a los que se hayan comunicado los datos personales rectificados, suprimidos o respecto de los que se ha limitado el tratamiento, conforme a lo establecido en el artículo 23 de esta Ley.'}, correct:'b', why:{b:'El art. 46 LO 7/2021 establece que el acceso, cesión, alteración y divulgación de datos al margen de los supuestos autorizados es infracción muy grave.'}},
{n:205, q:'De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, indique cuál de las siguientes infracciones es considerada de carácter grave.', o:{a:'El tratamiento de los datos de carácter personal cuando se incumplan los principios del artículo 6 de esta Ley.',b:'El incumplimiento del principio de transparencia de la información o del derecho de información del interesado establecido en el artículo 21 de esta Ley, cuando no se facilite toda la información exigida en dicha Ley Orgánica.',c:'El tratamiento de datos personales que vulnere los principios y garantías establecidos en el artículo 6 de esta ley, siempre que se causen perjuicios de carácter muy grave a los interesados.',d:'La transferencia temporal o definitiva de datos de carácter personal con destino a Estados que no sean miembros de la Unión Europea, incumpliendo las condiciones previstas en los artículos 43 y 47 de esta Ley.'}, correct:'a', why:{a:'El art. 46 LO 7/2021 establece que el tratamiento de datos incumpliendo los principios del art. 6 es infracción grave.'}},
{n:206, q:'De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, indique cuál de las siguientes infracciones es considerada de carácter muy grave.', o:{a:'La falta de designación de un delegado de protección de datos en los términos previstos en el artículo 40 de esta Ley.',b:'La utilización de los datos para una finalidad que no sea compatible con el objetivo para el que fueron recogidos, siempre que no se cuente con una base legal para ello.',c:'El incumplimiento de la llevanza de registros de actividades de tratamiento o del registro de operaciones.',d:'El incumplimiento de la obligación de suprimir los datos referidos a una persona fallecida cuando fuera exigible legalmente.'}, correct:'b', why:{b:'El art. 46 LO 7/2021 establece que la utilización de datos para finalidad incompatible sin base legal es infracción muy grave.'}},
{n:207, q:'De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, indique cuál de las siguientes infracciones es considerada de carácter leve.', o:{a:'El incumplimiento de la evaluación de impacto en la protección de los datos de carácter personal, si se derivan perjuicios o riesgos de carácter grave para los interesados.',b:'El incumplimiento de los plazos de conservación y revisión establecidos en virtud del artículo 8 de esta Ley.',c:'El incumplimiento de la obligación del encargado del tratamiento de informar al responsable del tratamiento acerca de una posible infracción de las disposiciones de esta Ley Orgánica, como consecuencia de una instrucción recibida de este.',d:'La adopción de decisiones individuales automatizadas sin las garantías señaladas en el artículo 14 de esta Ley.'}, correct:'c', why:{c:'El art. 46 LO 7/2021 establece que el incumplimiento del encargado de informar al responsable sobre posibles infracciones es infracción leve.'}},
{n:208, q:'De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, indique cuál de las siguientes infracciones es considerada de carácter grave.', o:{a:'No facilitar el acceso del personal de las autoridades de protección de datos competentes a los datos personales, información, locales, equipos y medios de tratamiento, cuando sean requeridos por las mismas, en el ejercicio de sus poderes de investigación.',b:'La negativa a proporcionar a las autoridades competentes la información necesaria para la prevención, detección, investigación y enjuiciamiento de infracciones penales.',c:'La notificación incompleta o defectuosa a la autoridad de protección de datos competente de la información relacionada con una violación de seguridad de los datos personales.',d:'La ausencia de adopción de aquellas medidas técnicas y organizativas que resulten apropiadas para aplicar de forma efectiva los principios de protección de datos, incluidas las medidas oportunas aplicar de forma efectiva desde el diseño y por defecto, así como para integrar las garantías necesarias en el tratamiento.'}, correct:'d', why:{d:'El art. 46 LO 7/2021 establece que la ausencia de medidas técnicas y organizativas para aplicar los principios de protección de datos es infracción grave.'}},
{n:209, q:'De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, indique cuál de las siguientes infracciones es considerada de carácter leve.', o:{a:'El incumplimiento de la obligación de llevanza de los registros de actividades de tratamiento o del registro de operaciones de tratamiento, si se causan perjuicios de carácter grave a los interesados.',b:'El incumplimiento de la evaluación de impacto en la protección de los datos de carácter personal, si se derivan perjuicios o riesgos de carácter grave para los interesados.',c:'La falta de formalización por los corresponsables del tratamiento del acuerdo que determine las obligaciones, funciones y responsabilidades respectivas, a propósito del tratamiento de datos personales y de sus relaciones con los interesados.',d:'La vulneración del deber de confidencialidad del encargado del tratamiento, establecido en el artículo 30 de esta Ley.'}, correct:'c', why:{c:'El art. 46 LO 7/2021 establece que la falta de formalización del acuerdo entre corresponsables es infracción leve.'}},
{n:210, q:'De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, indique la respuesta correcta.', o:{a:'Las infracciones muy graves se sancionan con multa de 360.001 a 2.000.000 euros.',b:'Las infracciones graves se sancionan con multa de 60.001 a 360.000 euros.',c:'Las leves se sancionan con multa de 3.000 a 60.000 euros.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 47 LO 7/2021 establece que las infracciones graves se sancionan con multa de 60.001 a 360.000 euros.'}},
{n:211, q:'De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, indique la respuesta que no es correcta.', o:{a:'Las infracciones muy graves prescriben a los tres años.',b:'Las infracciones graves prescriben a los dos años.',c:'Las infracciones leves prescriben a los tres meses.',d:'Interrumpirá la prescripción la iniciación, con conocimiento del interesado, del procedimiento sancionador, reiniciándose el plazo de prescripción si el expediente sancionador estuviere paralizado durante más de seis meses por causas no imputables al presunto infractor.'}, correct:'c', why:{c:'La opción c) es incorrecta: las infracciones leves prescriben al año (no a los tres meses) conforme al art. 48 LO 7/2021.'}},
{n:212, q:'De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, indique la respuesta que no es correcta.', o:{a:'Las sanciones impuestas por infracciones graves prescriben a los dos años.',b:'Las sanciones impuestas por infracciones muy graves prescriben a los tres años.',c:'Las sanciones impuestas por infracciones leves prescriben al año.',d:'La prescripción se interrumpirá por la iniciación, con conocimiento del interesado, del procedimiento de ejecución, volviendo a transcurrir el plazo si el mismo está paralizado durante más de tres meses por causa no imputable al infractor.'}, correct:'d', why:{d:'La opción d) es incorrecta: la prescripción de sanciones se interrumpe por la iniciación del procedimiento de ejecución, pero el plazo de paralización que vuelve a computar el plazo es distinto al descrito.'}},
{n:213, q:'De acuerdo con lo dispuesto en la Ley Orgánica 7/2021, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales, el plazo de caducidad de los procedimientos sancionadores es de...', o:{a:'Tres meses.',b:'Seis meses.',c:'Un año.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 48 LO 7/2021 establece que el plazo de caducidad de los procedimientos sancionadores es de seis meses.'}},
];
